/* Gerado a partir dos livros "O Grande Livro das Receitas Naturais" e "O Guia da Saúde Natural". */
window.LIVRO={"titulo": "O Grande Livro das Receitas Naturais", "capitulos": [{"id": "l1", "num": 1, "titulo": "Imunidade e defesas", "intro": "Ninguém \"aumenta\" a imunidade como se enche um tanque. O que se faz é dar condições ao sistema de defesa: dormir, comer bem, mover o corpo, reduzir o estresse — e oferecer, com constância, alimentos ricos em vitamina C, zinco, compostos de alho e cebola, mel e ervas aromáticas. As receitas deste capítulo são o apoio de sempre nos meses frios, nas viagens, nas fases de muito trabalho. Nenhuma delas impede uma infecção. Todas elas ajudam o corpo a estar mais bem servido.", "info": "img/cap/l01.webp", "capa": "img/rc/r001.webp", "receitas": [{"n": 1, "titulo": "Xarope de mel, alho e limão — o clássico da avó", "serve": "O preparo mais tradicional de todos. Apoia as defesas nos meses frios e acalma a garganta irritada.", "ing": ["4 dentes de alho", "Suco de 1 limão", "6 colheres de sopa de mel"], "preparo": "Amasse o alho e deixe descansar 10 minutos (é quando ele forma seus melhores compostos). Junte o suco do limão e o mel. Misture bem e guarde num pote de vidro limpo, na geladeira.", "uso": "1 colher de chá pela manhã, em jejum, por até 10 dias seguidos.", "dica": "Se o sabor for forte demais, dilua a colherada em meio copo de água morna.", "cautela": "Não dar a menores de 1 ano (mel). Quem toma anticoagulantes deve falar com o médico — o alho em quantidade pode potencializar o efeito. Refluxo e gastrite: pode incomodar.", "tags": ["Imunidade baixa", "Resfriado / gripe"]}, {"n": 2, "titulo": "Shot de gengibre, limão e cúrcuma", "serve": "O \"tiro\" matinal: aquece, apoia as defesas e desperta a digestão.", "ing": ["1 pedaço de gengibre fresco (3 cm)", "Suco de 1 limão", "½ colher de chá de cúrcuma em pó", "1 pitada de pimenta-do-reino", "100 ml de água", "Mel a gosto (opcional)"], "preparo": "Bata tudo no liquidificador e coe. Beba na hora.", "uso": "1 shot pela manhã, em jejum. Pode fazer todos os dias, ou nos períodos de mais desgaste.", "dica": "A pimenta não é enfeite: é ela que faz a cúrcuma ser aproveitada pelo corpo.", "cautela": "Gastrite e refluxo: tome após alguma comida. Pedra na vesícula: evite a cúrcuma em quantidade.", "tags": ["Imunidade baixa", "Resfriado / gripe"]}, {"n": 3, "titulo": "Chá de equinácea com limão", "serve": "A equinácea é a erva mais estudada no apoio às defesas nos primeiros sinais de resfriado.", "ing": ["1 colher de chá de equinácea seca (ou 1 sachê)", "200 ml de água", "Suco de ½ limão", "Mel a gosto"], "preparo": "Ferva a água, desligue, junte a equinácea e tampe por 10 minutos. Coe, junte o limão e o mel quando estiver morno.", "uso": "2 a 3 xícaras por dia, por no máximo 10 dias seguidos — depois faça uma pausa.", "dica": "Comece aos primeiros sinais: garganta arranhando, corpo pesado.", "cautela": "Evite se tem doença autoimune ou faz uso de imunossupressores. Alérgicos a plantas da família da margarida (camomila, arnica): atenção.", "tags": ["Imunidade baixa", "Resfriado / gripe"]}, {"n": 4, "titulo": "Chá de própolis e mel", "serve": "Própolis é a \"farmácia da colmeia\": apoia a garganta e as defesas.", "ing": ["10 a 15 gotas de extrato de própolis", "1 xícara de chá de camomila ou água morna", "1 colher de chá de mel"], "preparo": "Prepare o chá, deixe amornar, pingue o própolis e junte o mel.", "uso": "1 a 2 xícaras por dia nas fases de maior desgaste.", "dica": "O própolis mancha — cuidado com a roupa e os dentes (bochechar água depois ajuda).", "cautela": "Alérgicos a produtos de abelha: evite. Faça um teste com 1 gota antes.", "tags": ["Imunidade baixa"]}, {"n": 5, "titulo": "Suco de acerola, laranja e cenoura", "serve": "Vitamina C em abundância (a acerola é uma das campeãs) com betacaroteno da cenoura.", "ing": ["1 xícara de acerolas (frescas ou congeladas)", "Suco de 2 laranjas", "1 cenoura pequena", "200 ml de água"], "preparo": "Bata tudo, coe se preferir. Beba imediatamente.", "uso": "1 copo pela manhã, até 5 vezes por semana.", "dica": "Vitamina C se perde com luz, calor e tempo. Faça e beba — não guarde.", "cautela": "Diabéticos: prefira a versão sem laranja, ou tome junto de uma refeição.", "tags": ["Imunidade baixa"]}, {"n": 6, "titulo": "Leite dourado (golden milk)", "serve": "A bebida da noite: reconforta, apoia a imunidade e tem ação anti-inflamatória leve.", "ing": ["200 ml de leite (ou bebida vegetal)", "1 colher de chá de cúrcuma em pó", "1 pitada de pimenta-do-reino", "½ colher de chá de gengibre em pó", "1 pau de canela", "1 colher de chá de óleo de coco ou azeite", "Mel a gosto"], "preparo": "Aqueça tudo (menos o mel) em fogo baixo por 5 minutos, sem ferver. Coe e adoce.", "uso": "1 xícara à noite, antes de dormir.", "dica": "A gordura (óleo de coco) e a pimenta são o que permitem ao corpo aproveitar a cúrcuma. Não pule nenhuma das duas.", "cautela": "Pedra na vesícula e uso de anticoagulantes: converse com o médico antes de usar cúrcuma diariamente.", "tags": ["Imunidade baixa"]}, {"n": 7, "titulo": "Chá de sabugueiro", "serve": "Erva tradicional europeia de apoio nos resfriados e na febre leve, muito usada no inverno.", "ing": ["1 colher de sopa de flores secas de sabugueiro", "250 ml de água", "Mel e limão a gosto"], "preparo": "Ferva a água, desligue, junte as flores e tampe por 10 minutos. Coe.", "uso": "2 a 3 xícaras por dia, enquanto durar o desconforto.", "dica": "Use apenas as flores ou as bagas cozidas. Bagas cruas e outras partes da planta não devem ser consumidas.", "cautela": "Grávidas e lactantes: evite. Febre alta ou persistente é assunto de médico.", "tags": ["Imunidade baixa", "Resfriado / gripe"]}, {"n": 8, "titulo": "Sopa de alho, cebola e caldo de legumes", "serve": "O \"antibiótico da despensa\" em forma de sopa: reconfortante, hidratante e cheia de compostos de enxofre.", "ing": ["1 cabeça de alho (todos os dentes), picada", "2 cebolas grandes, fatiadas", "1 litro de caldo de legumes", "2 colheres de sopa de azeite", "Tomilho, sal e pimenta"], "preparo": "Refogue a cebola no azeite até dourar. Junte o alho e refogue 1 minuto (sem queimar). Junte o caldo e o tomilho e cozinhe 20 minutos. Bata se quiser cremosa.", "uso": "1 prato no jantar, 2 a 3 vezes por semana nos meses frios.", "dica": "Alho queimado fica amargo e perde valor. Fogo baixo, um minuto, e pronto.", "cautela": "Refluxo: a cebola e o alho podem incomodar; reduza a quantidade.", "tags": ["Imunidade baixa", "Resfriado / gripe"]}, {"n": 9, "titulo": "Chá de tomilho e limão", "serve": "Tomilho é aromático e tradicionalmente usado no apoio às vias respiratórias.", "ing": ["1 colher de chá de tomilho seco (ou 3 ramos frescos)", "250 ml de água", "Suco de ½ limão, mel a gosto"], "preparo": "Ferva a água, desligue, junte o tomilho e tampe 8 minutos. Coe, junte limão e mel.", "uso": "2 a 3 xícaras por dia, por até 7 dias.", "dica": "Tampar a xícara durante a infusão guarda os óleos aromáticos — que são justamente o que importa.", "cautela": "Grávidas: use apenas como tempero, não em chá concentrado.", "tags": ["Imunidade baixa", "Resfriado / gripe"]}, {"n": 10, "titulo": "Iogurte com mel, nozes e mirtilo", "serve": "Apoia o intestino — e um intestino bem cuidado é parte importante da defesa do corpo.", "ing": ["1 pote de iogurte natural", "1 colher de chá de mel", "1 punhado de nozes picadas", "½ xícara de mirtilos (ou morangos)"], "preparo": "Misture tudo na hora de comer.", "uso": "No café da manhã ou como lanche da tarde, diariamente.", "dica": "Iogurte natural, sem açúcar e sem sabor. O resto você põe.", "cautela": "Intolerância à lactose: use versões vegetais fermentadas.", "tags": ["Imunidade baixa"]}]}, {"id": "l2", "num": 2, "titulo": "Peso saudável e metabolismo", "intro": "Nenhum chá derrete gordura. Quem lhe disser o contrário está vendendo alguma coisa. O que estas receitas fazem — e fazem bem — é APOIAR QUEM JÁ ESTÁ NO CAMINHO: aumentam a saciedade, reduzem a vontade de beliscar, ajudam a digestão, substituem bebidas açucaradas por algo saboroso e sem calorias, e sustentam a energia para você conseguir se mover. Emagrecer é o resultado de comer de verdade, dormir, mover-se e ter paciência. Estas receitas são as companheiras desse processo — nunca o atalho.", "info": "img/cap/l02.webp", "capa": "img/rc/r011.webp", "receitas": [{"n": 11, "titulo": "Água de limão com gengibre e hortelã", "serve": "Substituir refrigerantes e sucos açucarados por algo saboroso, sem calorias e que ajuda a beber mais água.", "ing": ["1 litro de água", "1 limão em rodelas", "1 pedaço de gengibre (3 cm) em fatias", "1 punhado de folhas de hortelã"], "preparo": "Junte tudo numa jarra e deixe na geladeira por pelo menos 2 horas.", "uso": "Ao longo do dia, no lugar de outras bebidas.", "dica": "Troque a água a cada 24 horas.", "cautela": "Beba com canudo ou enxágue a boca depois: o ácido do limão, em excesso, desgasta o esmalte dos dentes."}, {"n": 12, "titulo": "Chá verde com limão", "serve": "O chá verde é o mais estudado no apoio ao metabolismo. Efeito modesto, mas real — e é excelente substituto do café da tarde.", "ing": ["1 colher de chá de folhas de chá verde (ou 1 sachê)", "200 ml de água a 80 °C (não fervendo)", "Suco de ½ limão"], "preparo": "Deixe em infusão por 3 minutos. Coe e junte o limão.", "uso": "2 a 3 xícaras por dia, entre as refeições. Evite após as 16h se você é sensível à cafeína.", "dica": "Água fervendo deixa o chá verde amargo. Ferva, espere 2 minutos, e só então despeje.", "cautela": "Contém cafeína: cuidado se tem insônia, ansiedade ou pressão descontrolada. Pode atrapalhar a absorção de ferro — não tome junto das refeições."}, {"n": 13, "titulo": "Mingau de aveia com canela e maçã", "serve": "O café da manhã que segura a fome até o almoço. Fibra solúvel + canela.", "ing": ["4 colheres de sopa de aveia em flocos", "200 ml de leite ou bebida vegetal", "½ maçã picada", "1 colher de chá de canela", "1 colher de chá de sementes de chia"], "preparo": "Cozinhe a aveia com o leite em fogo baixo, mexendo, por 5 minutos. Junte a maçã, a canela e a chia.", "uso": "No café da manhã, quantas vezes quiser.", "dica": "A aveia continua engrossando fora do fogo. Desligue um pouco antes do ponto.", "cautela": "Celíacos: use aveia certificada sem glúten.", "tags": ["Vontade de comer / compulsão"]}, {"n": 14, "titulo": "Água de chia com limão", "serve": "A chia incha na água e forma um gel que ocupa espaço no estômago: saciedade natural antes das refeições.", "ing": ["1 colher de sopa de sementes de chia", "250 ml de água", "Suco de ½ limão"], "preparo": "Misture a chia na água e deixe descansar 20 minutos, mexendo uma vez. Junte o limão.", "uso": "1 copo 20 minutos antes do almoço ou do jantar.", "dica": "Nunca coma chia seca \"a seco\" — sempre hidratada.", "cautela": "Beba bastante água ao longo do dia. Quem tem dificuldade de engolir deve evitar.", "tags": ["Vontade de comer / compulsão"]}, {"n": 15, "titulo": "Vinagre de maçã diluído antes das refeições", "serve": "Estudos sugerem que apoia o controle da glicemia após a refeição e aumenta a saciedade.", "ing": ["1 colher de sopa de vinagre de maçã", "1 copo grande de água (250 ml)"], "preparo": "Dilua bem. Só isso.", "uso": "1 copo antes do almoço, até 2 vezes ao dia.", "dica": "Beba com canudo e enxágue a boca depois.", "cautela": "Nunca puro. Gastrite, refluxo ou úlcera: evite. Quem usa diuréticos ou remédios para diabetes deve conversar com o médico.", "tags": ["Vontade de comer / compulsão"]}, {"n": 16, "titulo": "Sopa detox de legumes verdes", "serve": "Um jantar leve, saciante e de baixíssima densidade calórica.", "ing": ["1 abobrinha, 1 talo de aipo, ½ brócolis", "1 cebola, 1 dente de alho", "1 litro de caldo de legumes", "Azeite, sal, pimenta, salsa"], "preparo": "Refogue a cebola e o alho no azeite. Junte os legumes e o caldo. Cozinhe 20 minutos e bata.", "uso": "Como jantar, 3 a 4 vezes por semana.", "dica": "Um fio de azeite cru na hora de servir muda o sabor — e ajuda a absorver as vitaminas dos legumes.", "cautela": "Não faça disso a sua única refeição do dia. Sopa não substitui um prato completo."}, {"n": 17, "titulo": "Chá de hibisco", "serve": "Diurético leve, ajuda a reduzir a retenção de líquidos e a sensação de inchaço.", "ing": ["1 colher de chá de flores secas de hibisco", "250 ml de água"], "preparo": "Ferva a água, desligue, junte o hibisco e tampe por 5 minutos. Coe.", "uso": "1 a 2 xícaras por dia, por no máximo 10 dias seguidos. Depois faça uma pausa.", "dica": "Fica ótimo gelado, com uma rodela de laranja.", "cautela": "Pode baixar a pressão — cuidado se você já tem pressão baixa ou toma anti-hipertensivos. Grávidas: evite.", "tags": ["Inchaço / retenção"]}, {"n": 18, "titulo": "Smoothie verde de abacaxi, espinafre e gengibre", "serve": "Um café da manhã ou lanche que enche, hidrata e traz fibras e enzimas digestivas.", "ing": ["1 xícara de abacaxi (pode ser congelado)", "1 punhado de espinafre", "1 pedaço de gengibre (2 cm)", "200 ml de água", "Suco de ½ limão"], "preparo": "Bata tudo no liquidificador. Não coe — a fibra é parte do trabalho.", "uso": "1 copo pela manhã, até 5 vezes por semana.", "dica": "Congele o abacaxi em cubos: fica cremoso sem precisar de gelo.", "cautela": "Diabéticos: acompanhe de uma fonte de proteína (iogurte, castanhas)."}, {"n": 19, "titulo": "Café com canela (sem açúcar)", "serve": "Um jeito de largar o açúcar do café sem sofrer: a canela traz doçura sem calorias.", "ing": ["1 xícara de café", "½ colher de chá de canela em pó"], "preparo": "Misture a canela no pó de café antes de passar, ou direto na xícara.", "uso": "No lugar do café adoçado, todos os dias.", "dica": "Vá reduzindo o açúcar aos poucos, uma pitada por semana. Em um mês, você não sente falta.", "cautela": "Excesso de café: mais de 4 xícaras por dia pode causar insônia e palpitação."}, {"n": 20, "titulo": "Chá de dente-de-leão", "serve": "Tradicionalmente usado como diurético leve e apoio à digestão de gorduras.", "ing": ["1 colher de chá de raiz ou folhas secas de dente-de-leão", "250 ml de água"], "preparo": "Ferva, desligue, infusione 10 minutos, coe.", "uso": "1 a 2 xícaras por dia, por até 2 semanas.", "dica": "É amargo — o amargo é justamente o que estimula a digestão.", "cautela": "Pedra na vesícula, obstrução das vias biliares ou uso de diuréticos: fale com o médico antes.", "tags": ["Inchaço / retenção"]}]}, {"id": "l3", "num": 3, "titulo": "Açúcar no sangue em equilíbrio", "intro": "Aqui é preciso ser muito claro, porque é sério: nenhuma receita deste capítulo substitui o seu remédio para diabetes, nem os seus exames. Ninguém deve trocar metformina ou insulina por canela. O que estas receitas fazem é APOIAR — ajudam a suavizar o pico de açúcar depois da refeição, aumentam a fibra da alimentação, substituem bebidas doces. São coadjuvantes de um tratamento que quem conduz é o seu médico. E se você usa medicamento para baixar a glicemia, atenção dobrada: algumas destas receitas podem SOMAR-SE ao efeito do remédio e derrubar o açúcar demais. Converse com o seu médico e monitore.", "info": "img/cap/l03.webp", "capa": "img/rc/r021.webp", "receitas": [{"n": 21, "titulo": "Chá de canela", "serve": "A canela é a especiaria mais estudada no apoio ao controle da glicemia.", "ing": ["1 pau de canela (ou 1 colher de chá em pó)", "250 ml de água"], "preparo": "Ferva a água com o pau de canela por 5 minutos. Desligue, tampe e deixe 10 minutos. Coe.", "uso": "1 xícara por dia, de preferência depois de uma refeição.", "dica": "Prefira a canela do Ceilão para uso diário — a canela cássia (a comum) tem cumarina, que em excesso sobrecarrega o fígado.", "cautela": "Se você usa remédio para diabetes, monitore a glicemia: pode potencializar o efeito. Problemas de fígado: use com moderação.", "tags": ["Glicemia alta"]}, {"n": 22, "titulo": "Água de quiabo", "serve": "Receita tradicional brasileira. As mucilagens do quiabo formam um gel que retarda a absorção do açúcar.", "ing": ["2 quiabos frescos", "1 copo de água (250 ml)"], "preparo": "Corte as pontas dos quiabos e faça alguns cortes ao longo deles. Coloque no copo com água e deixe na geladeira de um dia para o outro. Pela manhã, retire os quiabos e beba a água.", "uso": "1 copo em jejum, pela manhã.", "dica": "A água fica viscosa — é normal, é justamente a mucilagem que interessa.", "cautela": "Se usa metformina, converse com o médico: há relatos de interferência na absorção. Monitore a glicemia.", "tags": ["Glicemia alta"]}, {"n": 23, "titulo": "Chá de folhas de amora", "serve": "Tradicionalmente usada no apoio ao controle da glicemia (contém compostos que retardam a quebra dos açúcares no intestino).", "ing": ["1 colher de chá de folhas secas de amoreira", "250 ml de água"], "preparo": "Ferva, desligue, infusione 10 minutos, coe.", "uso": "1 xícara junto ou logo antes de uma refeição rica em carboidrato.", "dica": "O momento importa: o efeito é sobre o açúcar daquela refeição.", "cautela": "Risco de hipoglicemia se combinado com medicamento. Monitore.", "tags": ["Glicemia alta"]}, {"n": 24, "titulo": "Vinagre de maçã antes do prato de massa", "serve": "Um dos apoios com melhor evidência: tomado antes de uma refeição com carboidrato, ajuda a reduzir o pico de glicemia.", "ing": ["1 colher de sopa de vinagre de maçã", "250 ml de água"], "preparo": "Dilua e beba 15 minutos antes da refeição.", "uso": "Antes das refeições mais ricas em carboidrato, até 2 vezes ao dia.", "dica": "Uma salada temperada com vinagre, antes do prato principal, faz o mesmo trabalho — e é mais gostosa.", "cautela": "Nunca puro. Gastrite, refluxo, úlcera: evite.", "tags": ["Glicemia alta"]}, {"n": 25, "titulo": "Chá de folha de goiabeira", "serve": "Muito usado na tradição brasileira; estudado por seu apoio ao controle da glicemia pós-refeição.", "ing": ["5 folhas de goiabeira lavadas (ou 1 colher de chá secas)", "250 ml de água"], "preparo": "Ferva a água, desligue, junte as folhas e tampe 10 minutos. Coe.", "uso": "1 xícara depois do almoço, até 5 vezes por semana.", "cautela": "Monitore a glicemia se usa medicação. Grávidas: evite.", "tags": ["Glicemia alta"]}, {"n": 26, "titulo": "Salada de folhas com azeite e vinagre antes da refeição", "serve": "A estratégia mais simples e eficaz de todas: comer fibra e gordura boa antes do carboidrato suaviza o pico de açúcar.", "ing": ["Folhas verdes variadas", "1 colher de sopa de azeite extravirgem", "1 colher de chá de vinagre", "Sal e pimenta"], "preparo": "Tempere e coma antes do prato principal.", "uso": "Todos os dias, no almoço e no jantar.", "dica": "A ordem em que se come importa quase tanto quanto o que se come. Fibras → proteína → carboidrato.", "cautela": "Nenhuma. Esta é para todos.", "tags": ["Glicemia alta"]}, {"n": 27, "titulo": "Farinha de banana verde no iogurte", "serve": "Rica em amido resistente, que se comporta como fibra: alimenta as bactérias boas e suaviza a glicemia.", "ing": ["1 colher de chá de biomassa ou farinha de banana verde", "1 pote de iogurte natural"], "preparo": "Misture bem.", "uso": "1 vez ao dia, no café da manhã ou lanche.", "dica": "Comece com meia colher: o intestino precisa se acostumar, ou dá gases.", "cautela": "Aumente a água ao longo do dia.", "tags": ["Glicemia alta"]}, {"n": 28, "titulo": "Chá de pata-de-vaca", "serve": "Conhecida na tradição popular brasileira como \"insulina vegetal\" — um apelido exagerado, mas a planta é tradicionalmente usada no apoio à glicemia.", "ing": ["1 colher de chá de folhas secas de pata-de-vaca", "250 ml de água"], "preparo": "Ferva, desligue, infusione 10 minutos, coe.", "uso": "1 xícara por dia, por no máximo 2 semanas seguidas.", "dica": "Apesar do apelido, não é insulina e não substitui insulina. Nunca.", "cautela": "Risco real de hipoglicemia em quem usa medicação. Fale com o médico. Grávidas: evite.", "tags": ["Glicemia alta"]}]}, {"id": "l4", "num": 4, "titulo": "Coração, pressão e colesterol", "intro": "O coração é um músculo teimoso: trabalha a vida inteira sem reclamar — até o dia em que reclama. O que ele pede é simples: menos sal, menos ultraprocessado, mais fibra, mais gordura boa, mais potássio, mais movimento e menos estresse. As receitas deste capítulo servem a esse pedido. Elas NÃO SUBSTITUEM o remédio de pressão nem a estatina. Elas somam.", "info": "img/cap/l04.webp", "capa": "img/rc/r029.webp", "receitas": [{"n": 29, "titulo": "Água de alho macerado", "serve": "O alho é um dos alimentos mais estudados no apoio à pressão e ao colesterol.", "ing": ["2 dentes de alho", "1 copo de água"], "preparo": "Amasse o alho, deixe descansar 10 minutos, junte a água e deixe de molho de um dia para o outro. Beba pela manhã (pode coar).", "uso": "1 copo em jejum, 5 vezes por semana.", "dica": "Os 10 minutos de descanso não são frescura: é o tempo de formação da alicina, o composto que interessa.", "cautela": "Anticoagulantes (varfarina, aspirina): o alho em quantidade pode aumentar o risco de sangramento. Converse com o médico. Suspenda 1 semana antes de cirurgias.", "tags": ["Pressão alta"]}, {"n": 30, "titulo": "Mingau de aveia diário", "serve": "A fibra solúvel (betaglucana) da aveia é uma das poucas coisas com evidência sólida no apoio à redução do colesterol LDL.", "ing": ["4 colheres de sopa de aveia", "200 ml de leite ou bebida vegetal", "Fruta e canela a gosto"], "preparo": "Cozinhe em fogo baixo por 5 minutos.", "uso": "No café da manhã, todos os dias. A constância é o segredo aqui.", "dica": "Cerca de 3 g de betaglucana por dia é o alvo — mais ou menos 40 g de aveia.", "cautela": "Nenhuma relevante. Celíacos: aveia certificada.", "tags": ["Colesterol alto"]}, {"n": 31, "titulo": "Chá de hibisco para a pressão", "serve": "Um dos chás com melhor evidência no apoio à redução da pressão arterial (efeito modesto, mas mensurável).", "ing": ["1 colher de chá de flores secas de hibisco", "250 ml de água"], "preparo": "Ferva, desligue, infusione 5 minutos, coe.", "uso": "1 a 2 xícaras por dia, por 2 a 4 semanas, com pausas.", "cautela": "Se você já toma anti-hipertensivo, monitore a pressão — pode somar. Pressão baixa e gravidez: evite.", "tags": ["Pressão alta"]}, {"n": 32, "titulo": "Suco de beterraba, maçã e cenoura", "serve": "A beterraba é rica em nitratos, que o corpo transforma em óxido nítrico — o que relaxa os vasos sanguíneos.", "ing": ["1 beterraba média", "1 maçã", "1 cenoura", "Suco de ½ limão", "200 ml de água"], "preparo": "Bata tudo e coe (ou não).", "uso": "1 copo, 3 a 4 vezes por semana, de preferência pela manhã.", "dica": "Beterraba crua tem mais nitratos que cozida.", "cautela": "Pode tingir a urina de rosa — é normal, não é sangue. Pedra nos rins (oxalato): consuma com moderação.", "tags": ["Pressão alta"]}, {"n": 33, "titulo": "Punhado de nozes e amêndoas", "serve": "Gordura boa, magnésio, vitamina E. As oleaginosas estão entre os alimentos mais associados à saúde cardiovascular.", "ing": ["1 punhado (cerca de 30 g) de nozes, amêndoas, castanhas"], "preparo": "Nenhum. É comer.", "uso": "1 punhado por dia, como lanche.", "dica": "Sem sal, sem açúcar, sem cobertura. Cruas ou levemente tostadas.", "cautela": "São calóricas — 1 punhado, não o pacote. Alergia a oleaginosas: óbvio, evite.", "tags": ["Colesterol alto"]}, {"n": 34, "titulo": "Peixe assado com azeite, alho e alecrim", "serve": "Ômega-3 dos peixes gordos + gordura boa do azeite: a dupla mais cardioprotetora da mesa.", "ing": ["1 filé de sardinha, salmão ou cavala", "2 colheres de sopa de azeite", "1 dente de alho, alecrim, limão, sal"], "preparo": "Tempere e asse por 20 minutos a 180 °C.", "uso": "2 a 3 vezes por semana.", "dica": "Sardinha em lata (em azeite, escorrida) resolve num dia corrido — e é barata.", "cautela": "Peixes grandes (atum, espadarte) acumulam mercúrio: prefira os pequenos.", "tags": ["Colesterol alto"]}, {"n": 35, "titulo": "Chá de folha de oliveira", "serve": "Tradicionalmente usado no Mediterrâneo no apoio à pressão e ao colesterol.", "ing": ["1 colher de chá de folhas secas de oliveira", "250 ml de água"], "preparo": "Ferva, desligue, infusione 10 minutos, coe.", "uso": "1 xícara por dia, por até 1 mês.", "cautela": "Pode baixar a pressão e a glicemia — atenção se você toma medicação para qualquer uma das duas.", "tags": ["Colesterol alto", "Pressão alta"]}, {"n": 36, "titulo": "Tempero sem sal (substituto do saleiro)", "serve": "Reduzir o sal é a medida mais eficaz que existe para a pressão. Este tempero devolve o sabor que o sal levava.", "ing": ["2 colheres de sopa de alho em pó", "2 colheres de sopa de cebola em pó", "1 colher de sopa de páprica", "1 colher de sopa de orégano seco", "1 colher de sopa de alecrim seco", "1 colher de chá de pimenta-do-reino", "Raspas secas de 1 limão"], "preparo": "Misture tudo e guarde num pote fechado.", "uso": "No lugar do sal, em tudo.", "dica": "O paladar se readapta em cerca de 3 semanas. Aguente firme: depois, a comida salgada de antes vai parecer intragável.", "cautela": "Cuidado com \"sal light\" à base de potássio se você tem problema renal ou usa certos remédios de pressão — fale com o médico.", "tags": ["Pressão alta"]}]}, {"id": "l5", "num": 5, "titulo": "Digestão e intestino", "intro": "O intestino é o segundo cérebro — e o primeiro a reclamar quando a vida aperta. Boa digestão não se conquista com remédio: conquista-se com fibra, água, ritmo, calma à mesa e as ervas certas na hora certa. Este é o capítulo mais útil do livro para o dia a dia.", "info": "img/cap/l05.webp", "capa": "img/rc/r037.webp", "receitas": [{"n": 37, "titulo": "Chá de camomila", "serve": "A erva mais gentil que existe: acalma o estômago irritado e os nervos que o irritaram.", "ing": ["1 colher de sopa de flores secas de camomila", "250 ml de água"], "preparo": "Ferva a água, desligue, junte a camomila, tampe e deixe 8 minutos. Coe.", "uso": "1 xícara depois das refeições ou antes de dormir.", "dica": "Tampar é essencial: os óleos aromáticos evaporam com o vapor.", "cautela": "Alérgicos à família da margarida (arnica, equinácea): atenção."}, {"n": 38, "titulo": "Chá de hortelã-pimenta", "serve": "Alivia a sensação de estômago pesado, os gases e o desconforto intestinal.", "ing": ["1 punhado de folhas frescas de hortelã (ou 1 colher de chá seca)", "250 ml de água"], "preparo": "Ferva, desligue, junte a hortelã, tampe 7 minutos. Coe.", "uso": "1 xícara depois das refeições pesadas.", "cautela": "Refluxo: evite. A hortelã relaxa a válvula do estômago e pode piorar a azia.", "tags": ["Gases"]}, {"n": 39, "titulo": "Chá de erva-doce (funcho)", "serve": "O clássico contra gases e cólicas — usado há séculos, inclusive em bebês (sob orientação).", "ing": ["1 colher de chá de sementes de erva-doce, levemente amassadas", "250 ml de água"], "preparo": "Amasse as sementes, ferva a água, desligue, infusione 10 minutos, coe.", "uso": "1 xícara depois das refeições, até 3 vezes ao dia.", "dica": "Amassar as sementes libera os óleos. Sem isso, o chá fica fraco.", "cautela": "Grávidas: use com moderação, e converse com o médico.", "tags": ["Gases"]}, {"n": 40, "titulo": "Chá de gengibre para náusea", "serve": "Uma das poucas plantas com evidência boa: o gengibre reduz náusea (inclusive a de enjoo de viagem e a da gravidez).", "ing": ["3 fatias finas de gengibre fresco", "250 ml de água"], "preparo": "Ferva a água com o gengibre por 5 minutos. Coe.", "uso": "Aos primeiros sinais de enjoo. Até 3 xícaras por dia.", "cautela": "Gestantes: até 1 g de gengibre por dia é considerado seguro, mas confirme com o obstetra. Cálculos biliares e anticoagulantes: cuidado.", "tags": ["Enjoo / náusea"]}, {"n": 41, "titulo": "Kefir de leite caseiro", "serve": "Probiótico vivo — um dos alimentos mais ricos em bactérias boas que existem, e você faz em casa.", "ing": ["1 colher de sopa de grãos de kefir", "500 ml de leite"], "preparo": "Coloque os grãos num vidro com o leite. Cubra com um pano (não feche hermeticamente). Deixe fora da geladeira por 24 horas. Coe: o líquido é o kefir; os grãos você reutiliza.", "uso": "1 copo por dia, sozinho ou batido com frutas.", "dica": "Nunca use utensílios de metal reativo (alumínio). Vidro, plástico ou inox.", "cautela": "Comece com meio copo — o intestino precisa se acostumar. Imunossuprimidos: converse com o médico."}, {"n": 42, "titulo": "Ameixa-preta hidratada", "serve": "O laxante natural mais confiável, e um dos mais estudados. Funciona.", "ing": ["4 ameixas secas", "1 copo de água"], "preparo": "Deixe as ameixas de molho na água de um dia para o outro.", "uso": "Coma as ameixas e beba a água, pela manhã, em jejum.", "dica": "O efeito aparece em 6 a 12 horas. Não adianta apressar.", "cautela": "Excesso causa cólica e diarreia. Comece com 3.", "tags": ["Constipação (intestino preso)"]}, {"n": 43, "titulo": "Linhaça moída no iogurte", "serve": "Fibra que regula o trânsito intestinal nos dois sentidos: solta o preso e firma o solto.", "ing": ["1 colher de sopa de linhaça moída na hora", "1 pote de iogurte natural"], "preparo": "Moa as sementes (no liquidificador ou moedor de café) e misture.", "uso": "1 colher por dia.", "dica": "Inteira, a linhaça passa direto sem fazer efeito. Moída, ela trabalha. E o óleo oxida rápido: moa na hora, ou guarde na geladeira por no máximo 1 semana.", "cautela": "Beba água. Sem água, fibra vira entupimento.", "tags": ["Constipação (intestino preso)"]}, {"n": 44, "titulo": "Chá de espinheira-santa", "serve": "A erva brasileira tradicionalmente usada no apoio à gastrite e à azia — protege a mucosa do estômago.", "ing": ["1 colher de chá de folhas secas de espinheira-santa", "250 ml de água"], "preparo": "Ferva, desligue, infusione 10 minutos, coe.", "uso": "1 xícara antes das refeições, 2 a 3 vezes ao dia, por até 4 semanas.", "cautela": "Grávidas e lactantes: não use. Gastrite persistente precisa de investigação médica (pode ser H. pylori).", "tags": ["Azia / gastrite"]}, {"n": 45, "titulo": "Suco de repolho e batata crua", "serve": "Receita tradicional de apoio à mucosa gástrica, usada há décadas contra a azia.", "ing": ["¼ de repolho branco", "1 batata pequena crua, descascada", "200 ml de água"], "preparo": "Bata tudo e coe. Beba imediatamente.", "uso": "½ copo em jejum, por até 10 dias.", "dica": "O sabor não é agradável. Uma maçã na receita ajuda muito.", "cautela": "Batata crua: use apenas batatas firmes, sem partes verdes ou brotos (que são tóxicos). Se tiver dúvida, não use.", "tags": ["Azia / gastrite"]}, {"n": 46, "titulo": "Água morna com limão em jejum", "serve": "Um ritual simples que hidrata, desperta o trânsito intestinal e prepara o estômago.", "ing": ["1 copo de água morna", "Suco de ½ limão"], "preparo": "Esprema e beba.", "uso": "Todas as manhãs, em jejum, 20 minutos antes do café.", "cautela": "Enxágue a boca depois (esmalte dos dentes). Gastrite ativa: pode arder — nesse caso, só água morna.", "tags": ["Azia / gastrite", "Constipação (intestino preso)"]}]}, {"id": "l6", "num": 6, "titulo": "Fígado e depuração", "intro": "Uma palavra honesta antes de começar: o seu fígado não precisa de \"detox\". Ele é o detox. Trabalha 24 horas por dia, sem folga, e não depende de suco verde para fazer o que já faz. O que a gente pode fazer é NÃO ATRAPALHAR (menos álcool, menos ultraprocessado, menos excesso) e facilitar o trabalho dele: hidratação, fibras, vegetais amargos, gorduras boas. É isso que este capítulo faz. Nada de \"limpeza de 3 dias\" — apenas hábitos que não sobrecarregam.", "info": "img/cap/l06.webp", "capa": "img/rc/r047.webp", "receitas": [{"n": 47, "titulo": "Chá de boldo", "serve": "O clássico brasileiro depois da comida pesada: apoia a digestão de gorduras.", "ing": ["1 folha de boldo (ou 1 colher de chá seco)", "250 ml de água"], "preparo": "Ferva a água, desligue, junte o boldo e tampe 10 minutos. Coe.", "uso": "1 xícara após uma refeição pesada. Não use todos os dias — no máximo 3 vezes por semana.", "cautela": "Grávidas, lactantes, quem tem obstrução das vias biliares ou doença hepática: não use. Uso prolongado não é recomendado."}, {"n": 48, "titulo": "Suco de limão com azeite em jejum", "serve": "Receita tradicional de estímulo suave da vesícula.", "ing": ["1 colher de sopa de azeite extravirgem", "Suco de ½ limão"], "preparo": "Misture e tome.", "uso": "Em jejum, 3 vezes por semana.", "cautela": "Quem tem pedra na vesícula deve evitar — o estímulo pode provocar uma crise. Fale com o médico."}, {"n": 49, "titulo": "Chá de alcachofra", "serve": "A alcachofra é uma das plantas mais estudadas no apoio à função hepática e à digestão de gorduras.", "ing": ["1 colher de sopa de folhas secas de alcachofra", "250 ml de água"], "preparo": "Ferva, desligue, infusione 10 minutos, coe.", "uso": "1 xícara antes das refeições, até 2 vezes ao dia.", "dica": "É bem amargo — e o amargo é o que funciona. Aguente.", "cautela": "Obstrução biliar: evite. Alérgicos à família da margarida: atenção."}, {"n": 50, "titulo": "Suco verde de couve, maçã e limão", "serve": "Vegetais crucíferos (couve) fornecem compostos que apoiam as enzimas de detoxificação do fígado.", "ing": ["2 folhas de couve", "1 maçã", "Suco de 1 limão", "1 pedaço de gengibre (2 cm)", "250 ml de água"], "preparo": "Bata tudo. Não coe.", "uso": "1 copo pela manhã, até 5 vezes por semana.", "cautela": "Quem usa varfarina: a couve é rica em vitamina K e pode interferir. Fale com o médico. Problemas de tireoide: consumo muito alto de crucíferas cruas merece moderação."}, {"n": 51, "titulo": "Chá de cardo-mariano (silimarina)", "serve": "A planta mais estudada de todas no apoio ao fígado. Seu composto, a silimarina, é usado inclusive em medicamentos.", "ing": ["1 colher de chá de sementes de cardo-mariano, amassadas", "250 ml de água"], "preparo": "Amasse as sementes, ferva a água, infusione 10 a 15 minutos, coe.", "uso": "1 a 2 xícaras por dia, por até 1 mês.", "cautela": "Alérgicos à família da margarida: atenção. Diabéticos: pode baixar a glicemia. Grávidas: converse com o médico."}, {"n": 52, "titulo": "Água com clorofila (salsa e limão)", "serve": "Hidratação com micronutrientes e clorofila; a salsa é diurética leve.", "ing": ["1 punhado de salsa fresca", "Suco de 1 limão", "500 ml de água"], "preparo": "Bata, coe e beba ao longo da manhã.", "uso": "3 a 4 vezes por semana.", "cautela": "Salsa em grande quantidade não é indicada na gravidez. Problemas renais: modere."}]}, {"id": "l7", "num": 7, "titulo": "Sono, ansiedade e estresse", "intro": "Aqui mora, talvez, a maior epidemia silenciosa do nosso tempo: gente que não dorme direito e não sabe mais o que é calma. Nenhum chá resolve a insônia sozinho. O que ele faz é criar um RITUAL — e o ritual é metade do trabalho. A xícara quente, a luz baixa, o telefone longe, o corpo entendendo que o dia acabou. Isso o corpo aprende. E aprende rápido. Estas receitas são as companheiras do fim do dia.", "info": "img/cap/l07.webp", "capa": "img/rc/r053.webp", "receitas": [{"n": 53, "titulo": "Chá de camomila com mel e lavanda", "serve": "O ritual clássico da noite. Camomila acalma, lavanda relaxa.", "ing": ["1 colher de sopa de flores de camomila", "1 pitada de flores de lavanda", "250 ml de água", "1 colher de chá de mel"], "preparo": "Ferva, desligue, junte as flores, tampe 8 minutos. Coe e adoce quando morno.", "uso": "1 xícara 40 minutos antes de dormir, todas as noites.", "dica": "Faça disso um ritual: mesma xícara, mesma hora, luz baixa. O corpo aprende o sinal.", "cautela": "Alérgicos à família da margarida: atenção.", "tags": ["Ansiedade", "Insônia", "Sono ruim"]}, {"n": 54, "titulo": "Chá de valeriana", "serve": "A erva mais tradicional para a insônia — atua como calmante suave.", "ing": ["1 colher de chá de raiz seca de valeriana", "250 ml de água"], "preparo": "Ferva, desligue, infusione 10 minutos, coe.", "uso": "1 xícara 1 hora antes de dormir. Use por períodos (2 a 4 semanas), não indefinidamente.", "dica": "O cheiro é... peculiar. Mel e limão ajudam.", "cautela": "Não combine com álcool, calmantes, ansiolíticos ou remédios para dormir — os efeitos se somam. Pode causar sonolência: não dirija. Grávidas: evite.", "tags": ["Insônia", "Sono ruim"]}, {"n": 55, "titulo": "Chá de maracujá (passiflora)", "serve": "Calmante suave, muito usado na ansiedade leve e no sono agitado.", "ing": ["1 colher de chá de folhas secas de maracujá (passiflora)", "250 ml de água"], "preparo": "Ferva, desligue, infusione 10 minutos, coe.", "uso": "1 xícara à noite, ou em momentos de tensão.", "dica": "A folha é a calmante — não a fruta.", "cautela": "Sonolência: não dirija. Não combine com calmantes. Grávidas: evite.", "tags": ["Ansiedade", "Insônia", "Sono ruim"]}, {"n": 56, "titulo": "Leite morno com noz-moscada e mel", "serve": "O reconforto da infância — e uma boa dose de triptofano, o precursor da melatonina.", "ing": ["200 ml de leite (ou bebida vegetal)", "1 pitada de noz-moscada ralada", "1 colher de chá de mel"], "preparo": "Aqueça o leite sem ferver, junte a noz-moscada e o mel.", "uso": "1 xícara antes de dormir.", "cautela": "Noz-moscada: apenas uma pitada. Em doses grandes é tóxica e alucinógena. Uma pitada, e ponto.", "tags": ["Insônia", "Sono ruim"]}, {"n": 57, "titulo": "Chá de melissa (erva-cidreira)", "serve": "Acalma o estômago nervoso e a mente agitada — perfeito para quem \"somatiza\" a ansiedade na barriga.", "ing": ["1 punhado de folhas frescas de melissa (ou 1 colher de chá secas)", "250 ml de água"], "preparo": "Ferva, desligue, tampe 8 minutos. Coe.", "uso": "2 a 3 xícaras por dia, nos momentos de tensão, e uma à noite.", "cautela": "Hipotireoidismo: uso prolongado pode interferir. Converse com o médico.", "tags": ["Ansiedade", "Sono ruim"]}, {"n": 58, "titulo": "Chá de mulungu", "serve": "A erva calmante brasileira por excelência, tradicionalmente usada na ansiedade e na insônia.", "ing": ["1 colher de chá de casca seca de mulungu", "250 ml de água"], "preparo": "Ferva a casca na água por 10 minutos. Desligue, tampe mais 5, coe.", "uso": "1 xícara à noite. Não use por longos períodos.", "cautela": "Pode potencializar calmantes e baixar a pressão. Não dirija após tomar. Grávidas: não use.", "tags": ["Ansiedade", "Insônia", "Sono ruim"]}, {"n": 59, "titulo": "Banho de ervas relaxante", "serve": "Às vezes o corpo precisa mais do que uma xícara. O banho quente com ervas aromáticas é um dos rituais mais antigos que existem.", "ing": ["1 punhado de lavanda, camomila e alecrim", "1 litro de água"], "preparo": "Ferva a água, desligue, junte as ervas, tampe por 15 minutos. Coe e despeje na banheira, ou use como enxágue final no banho.", "uso": "2 a 3 vezes por semana, à noite.", "cautela": "Teste numa pequena área da pele antes, se for sensível. Água muito quente não é boa para o coração nem para a pele.", "tags": ["Ansiedade", "Sono ruim"]}, {"n": 60, "titulo": "Óleo de lavanda no travesseiro", "serve": "A aromaterapia mais simples e mais estudada: o cheiro de lavanda está associado à redução da ansiedade e à melhora do sono.", "ing": ["2 a 3 gotas de óleo essencial de lavanda", "1 lenço ou algodão"], "preparo": "Pingue no lenço e coloque perto (não em cima) do travesseiro.", "uso": "Todas as noites.", "cautela": "Óleo essencial nunca vai direto na pele sem diluir, e nunca é ingerido. Asma: pode irritar, teste com cuidado.", "tags": ["Ansiedade", "Insônia", "Sono ruim"]}, {"n": 61, "titulo": "Chá de tília", "serve": "Suave, floral, relaxante. Ótimo para as noites em que a cabeça não desliga.", "ing": ["1 colher de sopa de flores secas de tília", "250 ml de água"], "preparo": "Ferva, desligue, tampe 10 minutos, coe.", "uso": "1 xícara à noite.", "cautela": "Problemas cardíacos: uso muito frequente e prolongado não é recomendado. Converse com o médico.", "tags": ["Ansiedade", "Insônia", "Sono ruim"]}]}, {"id": "l8", "num": 8, "titulo": "Energia e disposição", "intro": "Cansaço crônico não se resolve com café. Café só empurra a conta para mais tarde. O que sustenta a energia de verdade é: sono, ferro e vitamina B12 em ordem, açúcar no sangue estável (sem picos e quedas), hidratação e movimento. As receitas deste capítulo apoiam exatamente isso — e substituem o quinto café do dia por algo que não rouba o seu sono. AVISO IMPORTANTE: cansaço que não passa, mesmo com boas noites de sono, merece exames. Anemia, tireoide e deficiência de B12 são causas comuns e tratáveis. Não normalize o cansaço.", "info": "img/cap/l08.webp", "capa": "img/rc/r062.webp", "receitas": [{"n": 62, "titulo": "Chá de guaraná em pó", "serve": "Estimulante natural brasileiro. A cafeína do guaraná é liberada mais lentamente que a do café — energia sem o pico e a queda.", "ing": ["½ colher de chá de guaraná em pó", "200 ml de água quente ou suco"], "preparo": "Dissolva bem.", "uso": "Pela manhã ou no início da tarde. Nunca depois das 16h.", "cautela": "Contém cafeína: cuidado com insônia, ansiedade, palpitações, pressão alta. Não combine com muitos cafés no mesmo dia.", "tags": ["Cansaço / falta de energia"]}, {"n": 63, "titulo": "Vitamina de banana, aveia e pasta de amendoim", "serve": "Energia que dura: carboidrato + fibra + gordura boa + proteína. O melhor pré-treino caseiro que existe.", "ing": ["1 banana", "3 colheres de sopa de aveia", "1 colher de sopa de pasta de amendoim", "250 ml de leite ou bebida vegetal", "1 pitada de canela"], "preparo": "Bata tudo.", "uso": "No café da manhã ou 1 hora antes de se exercitar.", "dica": "Congele a banana em rodelas: fica cremoso como um milk-shake.", "cautela": "Alergia a amendoim: substitua por tahine ou pasta de castanha.", "tags": ["Cansaço / falta de energia"]}, {"n": 64, "titulo": "Chá de ginseng", "serve": "Adaptógeno tradicional, usado há milênios no apoio à disposição física e mental.", "ing": ["1 colher de chá de raiz seca de ginseng", "250 ml de água"], "preparo": "Ferva a raiz por 10 minutos. Coe.", "uso": "1 xícara pela manhã, em ciclos de 3 a 4 semanas, com pausas.", "cautela": "Pode elevar a pressão e causar insônia. Interage com anticoagulantes e antidiabéticos. Grávidas: evite.", "tags": ["Cansaço / falta de energia"]}, {"n": 65, "titulo": "Suco de beterraba antes do exercício", "serve": "Os nitratos da beterraba melhoram a eficiência do uso de oxigênio pelo músculo — é uma das poucas coisas com evidência real em desempenho.", "ing": ["1 beterraba média", "1 maçã", "Suco de ½ limão", "200 ml de água"], "preparo": "Bata e coe.", "uso": "1 copo, 2 a 3 horas antes do exercício.", "cautela": "Urina rosada é normal. Pedra nos rins: modere.", "tags": ["Cansaço / falta de energia"]}, {"n": 66, "titulo": "Água de coco com limão e sal (isotônico caseiro)", "serve": "Repõe água e eletrólitos depois do suor — sem os corantes e o açúcar das bebidas esportivas.", "ing": ["500 ml de água de coco", "Suco de ½ limão", "1 pitada de sal"], "preparo": "Misture.", "uso": "Depois de exercício, calor forte ou suor intenso.", "cautela": "Problemas renais ou dieta com restrição de potássio: água de coco é riquíssima em potássio — fale com o médico.", "tags": ["Cansaço / falta de energia"]}, {"n": 67, "titulo": "Chá de alecrim", "serve": "Aromático e estimulante suave; tradicionalmente associado à clareza mental e à disposição.", "ing": ["1 ramo de alecrim fresco (ou 1 colher de chá seco)", "250 ml de água"], "preparo": "Ferva, desligue, tampe 8 minutos, coe.", "uso": "1 xícara pela manhã ou no meio da tarde.", "cautela": "Grávidas: use apenas como tempero. Epilepsia e pressão alta: use com moderação.", "tags": ["Cansaço / falta de energia"]}, {"n": 68, "titulo": "Bolinhas energéticas de tâmara e cacau", "serve": "Um lanche de verdade para a queda das 16h — em vez do biscoito da máquina.", "ing": ["10 tâmaras sem caroço", "1 xícara de aveia", "2 colheres de sopa de cacau em pó", "2 colheres de sopa de pasta de amendoim", "1 pitada de sal"], "preparo": "Bata tudo no processador até formar uma massa. Faça bolinhas e leve à geladeira por 1 hora.", "uso": "1 a 2 bolinhas como lanche.", "dica": "Duram 1 semana na geladeira, num pote fechado.", "cautela": "São calóricas e doces (tâmara é açúcar de fruta). Diabéticos: modere.", "tags": ["Cansaço / falta de energia"]}]}, {"id": "l9", "num": 9, "titulo": "Inflamação, dores e articulações", "intro": "A inflamação é uma coisa boa — é assim que o corpo se defende e se repara. O problema é quando ela não vai embora: fica ali, baixa e crônica, corroendo articulações, vasos e nervos ao longo dos anos. Não existe um alimento que apague a inflamação crônica. Existe um PADRÃO ALIMENTAR que a reduz: menos ultraprocessado, menos açúcar, menos álcool — e mais azeite, peixe, vegetais coloridos, especiarias. Estas receitas fazem parte desse padrão. E algumas ajudam nas dores do dia.", "info": "img/cap/l09.webp", "capa": "img/rc/r069.webp", "receitas": [{"n": 69, "titulo": "Pasta de cúrcuma (a base de tudo)", "serve": "A forma mais eficiente de usar cúrcuma no dia a dia — com a gordura e a pimenta que o corpo precisa para aproveitá-la.", "ing": ["½ xícara de cúrcuma em pó", "1 xícara de água", "1 colher de chá de pimenta-do-reino moída", "3 colheres de sopa de óleo de coco ou azeite"], "preparo": "Cozinhe a cúrcuma com a água em fogo baixo, mexendo, até virar uma pasta (uns 7 minutos). Desligue, junte a pimenta e o óleo. Guarde num vidro na geladeira.", "uso": "1 colher de chá por dia — no leite dourado, na sopa, no arroz, no ovo mexido.", "dica": "Dura até 2 semanas na geladeira. É a base das outras receitas com cúrcuma.", "cautela": "Pedra na vesícula, anticoagulantes, cirurgia próxima: converse com o médico.", "tags": ["Dor nas articulações", "Inflamação crônica"]}, {"n": 70, "titulo": "Leite dourado anti-inflamatório", "serve": "A versão noturna, reconfortante, da cúrcuma.", "ing": ["200 ml de leite ou bebida vegetal", "1 colher de chá da pasta de cúrcuma (receita 69)", "1 pitada de canela Mel a gosto"], "preparo": "Aqueça sem ferver, misture bem.", "uso": "1 xícara à noite.", "cautela": "Mesmas da cúrcuma.", "tags": ["Inflamação crônica"]}, {"n": 71, "titulo": "Chá de gengibre e cúrcuma para dores articulares", "serve": "Os dois anti-inflamatórios naturais mais estudados, juntos.", "ing": ["3 fatias de gengibre fresco", "1 colher de chá de cúrcuma", "1 pitada de pimenta-do-reino", "300 ml de água", "Mel e limão a gosto"], "preparo": "Ferva a água com o gengibre e a cúrcuma por 8 minutos. Coe, junte pimenta, mel e limão.", "uso": "1 a 2 xícaras por dia.", "cautela": "Anticoagulantes: gengibre e cúrcuma somam efeito. Fale com o médico.", "tags": ["Dor nas articulações", "Inflamação crônica"]}, {"n": 72, "titulo": "Compressa quente de gengibre", "serve": "Alívio local para articulações rígidas e músculos tensos — o calor relaxa e o gengibre aumenta o fluxo de sangue.", "ing": ["1 pedaço grande de gengibre ralado", "1 litro de água quente", "1 pano de algodão"], "preparo": "Ferva a água com o gengibre, desligue e deixe 10 minutos. Molhe o pano, torça e aplique quente (não escaldante) sobre a região.", "uso": "15 a 20 minutos, 1 a 2 vezes ao dia.", "cautela": "Nunca em pele ferida, inflamada, com vermelhidão ou inchaço agudo. Diabéticos com neuropatia: cuidado, a sensibilidade ao calor pode estar reduzida — risco de queimadura.", "tags": ["Cãibras / dores musculares", "Dor nas articulações"]}, {"n": 73, "titulo": "Chá de garra-do-diabo (harpagophytum)", "serve": "Planta africana com boa tradição de uso no apoio às dores articulares.", "ing": ["1 colher de chá de raiz seca", "250 ml de água"], "preparo": "Ferva por 10 minutos, coe.", "uso": "1 a 2 xícaras por dia, por até 8 semanas.", "cautela": "Úlcera e gastrite: evite. Interage com anticoagulantes e remédios cardíacos. Grávidas: não use.", "tags": ["Dor nas articulações"]}, {"n": 74, "titulo": "Suco de cereja para dor muscular", "serve": "A cereja azeda é uma das poucas frutas com evidência no apoio à recuperação muscular e à redução da dor pós-exercício.", "ing": ["1 xícara de cerejas (frescas ou congeladas)", "200 ml de água"], "preparo": "Bata e coe.", "uso": "1 copo depois de exercício intenso.", "cautela": "Ácido úrico alto/gota: a cereja é, aliás, tradicionalmente usada nesse caso — mas confirme com o médico.", "tags": ["Cãibras / dores musculares"]}, {"n": 75, "titulo": "Azeite extravirgem cru, todos os dias", "serve": "O azeite contém oleocantal, um composto com ação anti-inflamatória comparável (em escala muito menor) à do ibuprofeno.", "ing": ["2 colheres de sopa de azeite extravirgem"], "preparo": "Nenhum. Use cru, sobre a comida pronta.", "uso": "Todos os dias, sobre salada, sopa, legumes, pão.", "dica": "Um azeite bom \"arranha\" a garganta ao descer. Esse arranhão é o oleocantal. É sinal de qualidade.", "cautela": "É calórico. Duas colheres, não meia garrafa.", "tags": ["Dor nas articulações", "Inflamação crônica"]}, {"n": 76, "titulo": "Chá de salgueiro (a aspirina da natureza)", "serve": "A casca do salgueiro contém salicina — o composto que deu origem à aspirina. Tradicionalmente usado para dores e febre.", "ing": ["1 colher de chá de casca seca de salgueiro", "250 ml de água"], "preparo": "Ferva por 10 minutos, coe.", "uso": "1 xícara, no máximo 2 por dia, por poucos dias.", "cautela": "Alergia a aspirina: não use. Úlcera, gastrite, anticoagulantes, asma: evite. Nunca em crianças (risco de síndrome de Reye). Grávidas: não use. Esta é uma das receitas mais potentes — e mais perigosas — deste livro. Respeite-a."}]}, {"id": "l10", "num": 10, "titulo": "Garganta, tosse e vias respiratórias", "intro": "Este é o capítulo dos meses frios. Da garganta que arranha, do nariz entupido, da tosse que não deixa dormir. Nada aqui cura uma infecção — vírus vão embora sozinhos, e bactéria pede antibiótico prescrito por médico. O que estas receitas fazem é ALIVIAR OS SINTOMAS enquanto o corpo faz o trabalho dele. E fazem isso bem: o mel, por exemplo, tem estudos mostrando que alivia a tosse noturna em crianças melhor do que xaropes de farmácia. PROCURE UM MÉDICO SE: a febre passar de 3 dias, faltar ar, houver dor forte no peito, ou a tosse durar mais de 3 semanas.", "info": "img/cap/l10.webp", "capa": "img/rc/r077.webp", "receitas": [{"n": 77, "titulo": "Xarope de mel e limão", "serve": "O mais simples e um dos mais eficazes: o mel forma uma película que acalma a garganta irritada e reduz a tosse.", "ing": ["4 colheres de sopa de mel", "Suco de 1 limão"], "preparo": "Misture. Guarde num vidro, na geladeira.", "uso": "1 colher de chá a cada 4 horas, e uma antes de dormir.", "cautela": "Nunca em menores de 1 ano — risco de botulismo. Diabéticos: modere.", "tags": ["Dor de garganta", "Tosse seca"]}, {"n": 78, "titulo": "Xarope de cebola roxa", "serve": "Receita de avó por excelência. A cebola é rica em compostos de enxofre e quercetina; o xarope acalma a tosse.", "ing": ["1 cebola roxa em rodelas", "4 colheres de sopa de mel (ou açúcar mascavo)"], "preparo": "Num pote, alterne camadas de cebola e mel. Tampe e deixe descansar 8 a 12 horas (de um dia para o outro). Vai se formar um xarope no fundo. Coe.", "uso": "1 colher de chá, 3 a 4 vezes ao dia.", "dica": "Dura 3 dias na geladeira. O cheiro é forte, o sabor é surpreendentemente bom.", "cautela": "Menores de 1 ano: não (mel). Refluxo: pode incomodar.", "tags": ["Dor de garganta", "Tosse com catarro"]}, {"n": 79, "titulo": "Gargarejo de água morna com sal", "serve": "O alívio mais barato do mundo para a dor de garganta — e um dos que mais funcionam.", "ing": ["1 copo de água morna", "½ colher de chá de sal"], "preparo": "Dissolva o sal.", "uso": "Gargareje por 30 segundos e cuspa. 3 a 4 vezes ao dia.", "cautela": "Não engula. Crianças pequenas: só quando souberem gargarejar sem engolir.", "tags": ["Dor de garganta"]}, {"n": 80, "titulo": "Inalação de vapor com eucalipto", "serve": "Descongestiona o nariz e alivia a sensação de peito fechado.", "ing": ["1 litro de água fervente", "3 gotas de óleo essencial de eucalipto (ou 1 punhado de folhas)"], "preparo": "Coloque a água numa bacia, junte o eucalipto. Cubra a cabeça com uma toalha e inale o vapor por 10 minutos, com os olhos fechados.", "uso": "1 a 2 vezes ao dia.", "cautela": "Cuidado com queimaduras (mantenha distância do vapor). Não use eucalipto em crianças pequenas nem em asmáticos — pode causar broncoespasmo. Nesse caso, use só o vapor de água.", "tags": ["Congestão nasal"]}, {"n": 81, "titulo": "Chá de gengibre, mel e limão para a garganta", "serve": "A tríade clássica: aquece, acalma e alivia.", "ing": ["4 fatias de gengibre fresco", "300 ml de água", "Suco de ½ limão", "1 colher de sopa de mel"], "preparo": "Ferva a água com o gengibre por 8 minutos. Coe, deixe amornar, junte limão e mel.", "uso": "2 a 3 xícaras por dia enquanto durarem os sintomas.", "dica": "Nunca ponha mel na água fervendo — o calor destrói seus compostos. Espere amornar.", "cautela": "Menores de 1 ano: não.", "tags": ["Dor de garganta", "Resfriado / gripe"]}, {"n": 82, "titulo": "Lavagem nasal com soro fisiológico", "serve": "Simples, seguro e eficaz: limpa o muco e alivia a congestão e a sinusite. Recomendado inclusive por médicos.", "ing": ["250 ml de soro fisiológico (0,9%) morno", "Ou: 250 ml de água fervida e resfriada + ½ colher de chá de sal + 1 pitada de bicarbonato"], "preparo": "Misture bem, se for caseiro.", "uso": "Com uma seringa sem agulha ou um dispositivo próprio, incline a cabeça sobre a pia e lave uma narina de cada vez, deixando sair pela outra. 1 a 2 vezes ao dia.", "dica": "A água precisa ser fervida ou destilada. Água de torneira direto no nariz é perigoso — pode carregar microrganismos.", "cautela": "Ouvido tampado ou infecção de ouvido: pare e procure um médico.", "tags": ["Congestão nasal", "Sinusite"]}, {"n": 83, "titulo": "Chá de alteia (marshmallow) para tosse seca", "serve": "A raiz de alteia é rica em mucilagem: forma uma película protetora sobre a garganta irritada.", "ing": ["1 colher de chá de raiz seca de alteia", "250 ml de água fria"], "preparo": "Deixe a raiz de molho em água fria por 2 horas (o calor destrói a mucilagem). Coe. Aqueça levemente se quiser.", "uso": "2 a 3 xícaras por dia.", "dica": "É a única infusão deste livro que se faz a frio — e o motivo é justamente esse.", "cautela": "Pode retardar a absorção de outros medicamentos: espaçe 1 hora.", "tags": ["Tosse seca"]}, {"n": 84, "titulo": "Chá de tomilho e mel para tosse produtiva", "serve": "O tomilho é tradicionalmente usado como expectorante — ajuda a soltar o catarro.", "ing": ["1 colher de chá de tomilho seco", "250 ml de água", "1 colher de chá de mel"], "preparo": "Ferva, desligue, tampe 10 minutos, coe. Adoce quando morno.", "uso": "3 xícaras por dia, por até 7 dias.", "cautela": "Grávidas: apenas como tempero.", "tags": ["Tosse com catarro"]}, {"n": 85, "titulo": "Mel com própolis e gengibre (xarope reforçado)", "serve": "O xarope mais completo do livro para os dias de garganta ruim.", "ing": ["6 colheres de sopa de mel", "1 colher de chá de gengibre ralado", "20 gotas de extrato de própolis", "Suco de ½ limão"], "preparo": "Misture tudo. Guarde na geladeira, num vidro escuro se possível.", "uso": "1 colher de chá, até 4 vezes ao dia.", "dica": "Dura 2 semanas na geladeira.", "cautela": "Menores de 1 ano: não. Alérgicos a produtos de abelha: evite.", "tags": ["Dor de garganta"]}]}, {"id": "l11", "num": 11, "titulo": "Pele, cabelo e unhas", "intro": "A pele é o espelho de dentro. Nenhum creme resolve o que a alimentação, o sono e a água estragam. Dito isso, há preparos caseiros que funcionam de verdade — e são muito mais baratos que a prateleira da farmácia. REGRA DE OURO: faça sempre um teste numa pequena área (atrás da orelha ou no antebraço) 24 horas antes de usar qualquer preparo no rosto. Pele é imprevisível.", "info": "img/cap/l11.webp", "capa": "img/rc/r086.webp", "receitas": [{"n": 86, "titulo": "Máscara de mel e aveia", "serve": "Hidrata, acalma a irritação e esfolia suavemente. Boa para praticamente todos os tipos de pele.", "ing": ["1 colher de sopa de mel", "1 colher de sopa de aveia moída fina", "1 colher de chá de iogurte natural"], "preparo": "Misture até formar uma pasta.", "uso": "Aplique no rosto limpo, deixe 15 minutos, enxágue com água morna. 1 a 2 vezes por semana.", "cautela": "Faça o teste de alergia antes.", "tags": ["Pele seca / irritada"]}, {"n": 87, "titulo": "Tônico de chá verde para a pele", "serve": "Antioxidante, adstringente leve, ajuda no controle da oleosidade.", "ing": ["1 xícara de chá verde forte, frio", "1 colher de chá de vinagre de maçã (opcional)"], "preparo": "Prepare o chá, deixe esfriar completamente, guarde num frasco com borrifador, na geladeira.", "uso": "Borrife ou aplique com algodão depois da limpeza, 1 a 2 vezes ao dia.", "dica": "Dura 5 dias na geladeira.", "cautela": "Pele muito seca: pule o vinagre.", "tags": ["Pele oleosa / acne"]}, {"n": 88, "titulo": "Óleo de coco e açúcar (esfoliante corporal)", "serve": "Remove células mortas e hidrata ao mesmo tempo. Deixa a pele lisa.", "ing": ["½ xícara de açúcar", "¼ de xícara de óleo de coco", "Raspas de limão ou algumas gotas de óleo essencial"], "preparo": "Misture até formar uma pasta granulosa.", "uso": "No banho, em movimentos circulares, 1 a 2 vezes por semana. Enxágue.", "cautela": "Só no corpo, não no rosto (o açúcar é abrasivo demais para a pele facial). Cuidado: deixa o box escorregadio."}, {"n": 89, "titulo": "Máscara de argila verde", "serve": "Absorve a oleosidade e limpa os poros em profundidade.", "ing": ["2 colheres de sopa de argila verde em pó", "Água (ou chá verde) o suficiente para formar uma pasta"], "preparo": "Misture numa tigela não metálica (a argila reage com o metal), até virar um creme.", "uso": "Aplique, deixe 10 a 15 minutos — não deixe secar e rachar — e enxágue. 1 vez por semana.", "cautela": "Pele seca ou sensível: use apenas na zona T, ou evite.", "tags": ["Pele oleosa / acne"]}, {"n": 90, "titulo": "Óleo de rícino e alecrim para o cabelo", "serve": "Fortalece o fio e estimula o couro cabeludo. O alecrim tem estudos promissores no apoio ao crescimento capilar.", "ing": ["2 colheres de sopa de óleo de rícino", "2 colheres de sopa de óleo de coco", "5 gotas de óleo essencial de alecrim"], "preparo": "Misture e aqueça levemente (morno, não quente).", "uso": "Massageie o couro cabeludo por 5 minutos, deixe agir 1 hora (ou a noite toda), lave normalmente. 1 vez por semana.", "cautela": "Grávidas: evite óleo essencial de alecrim.", "tags": ["Cabelo (queda, fraqueza)"]}, {"n": 91, "titulo": "Enxágue de vinagre de maçã para o cabelo", "serve": "Devolve o brilho, remove o resíduo de produtos e fecha a cutícula do fio.", "ing": ["2 colheres de sopa de vinagre de maçã", "500 ml de água"], "preparo": "Dilua.", "uso": "Depois do xampu, despeje sobre os cabelos, massageie e enxágue. 1 vez por semana.", "cautela": "Sempre diluído. Cabelos coloridos: pode desbotar; teste numa mecha.", "tags": ["Cabelo (queda, fraqueza)"]}, {"n": 92, "titulo": "Suco de colágeno natural (vitamina C + proteína)", "serve": "O corpo produz colágeno — mas só consegue fazê-lo se tiver vitamina C e aminoácidos. Este suco fornece os dois.", "ing": ["1 laranja", "1 punhado de morangos", "1 colher de sopa de gelatina sem sabor (ou colágeno em pó)", "200 ml de água"], "preparo": "Bata tudo.", "uso": "1 copo por dia, pela manhã.", "dica": "A vitamina C não é opcional: sem ela, o corpo não monta o colágeno. Elas trabalham juntas.", "cautela": "Nenhuma relevante."}]}, {"id": "l12", "num": 12, "titulo": "Rins e vias urinárias", "intro": "Os rins pedem pouca coisa: água. Muita, todos os dias. Depois disso, pedem menos sal e menos excesso de proteína. As receitas deste capítulo apoiam a hidratação e o funcionamento das vias urinárias. Elas NÃO TRATAM INFECÇÃO URINÁRIA — infecção urinária arde, urge, às vezes dá febre, e precisa de médico e, quase sempre, de antibiótico. Não deixe para depois: uma cistite mal cuidada sobe para o rim.", "info": "img/cap/l12.webp", "capa": "img/rc/r093.webp", "receitas": [{"n": 93, "titulo": "Suco de cranberry (oxicoco) sem açúcar", "serve": "O cranberry contém proantocianidinas, que dificultam a aderência de bactérias à parede da bexiga. É o preparo mais estudado na prevenção de infecções urinárias de repetição.", "ing": ["200 ml de suco de cranberry puro, sem açúcar", "Água para diluir (opcional)"], "preparo": "Beba puro ou diluído.", "uso": "1 copo por dia, como prevenção em quem tem infecções de repetição.", "dica": "Os sucos de cranberry adoçados do supermercado têm pouquíssimo cranberry e muito açúcar — não servem.", "cautela": "Não trata infecção instalada. Interage com varfarina. Histórico de pedra nos rins (oxalato): converse com o médico.", "tags": ["Infecção urinária (prevenção)"]}, {"n": 94, "titulo": "Chá de cavalinha", "serve": "Diurético tradicional, apoia a eliminação de líquidos.", "ing": ["1 colher de chá de cavalinha seca", "250 ml de água"], "preparo": "Ferva, desligue, infusione 10 minutos, coe.", "uso": "1 xícara por dia, por no máximo 1 semana seguida.", "cautela": "Uso prolongado não é seguro (pode reduzir a vitamina B1). Problemas renais ou cardíacos, gravidez: não use. Quem toma diuréticos: fale com o médico.", "tags": ["Inchaço / retenção"]}, {"n": 95, "titulo": "Chá de quebra-pedra", "serve": "O nome diz a fama: é a planta brasileira mais tradicional no apoio às vias urinárias e à eliminação de pequenos cálculos.", "ing": ["1 colher de chá da planta seca", "250 ml de água"], "preparo": "Ferva, desligue, infusione 10 minutos, coe.", "uso": "1 a 2 xícaras por dia, por até 2 semanas.", "cautela": "Cálculo grande é emergência médica — dor forte no flanco, sangue na urina, febre: vá ao hospital. Pode baixar pressão e glicemia. Grávidas: não use."}, {"n": 96, "titulo": "Água de melancia com hortelã", "serve": "Hidratação saborosa e diurético natural suave — a melancia é 92% água.", "ing": ["2 xícaras de melancia em cubos", "1 punhado de hortelã", "Suco de ½ limão"], "preparo": "Bata, coe se quiser.", "uso": "1 a 2 copos por dia, especialmente no calor.", "cautela": "Diabéticos: modere (a melancia tem índice glicêmico alto)."}, {"n": 97, "titulo": "Chá de salsa (salsinha)", "serve": "Diurético leve e tradicional, usado no apoio à retenção de líquidos.", "ing": ["1 punhado de salsa fresca", "250 ml de água"], "preparo": "Ferva a água, desligue, junte a salsa, tampe 10 minutos, coe.", "uso": "1 xícara por dia, por poucos dias seguidos.", "cautela": "Gravidez: não use (em quantidade, pode estimular contrações). Doença renal: fale com o médico antes de usar qualquer diurético.", "tags": ["Inchaço / retenção"]}]}, {"id": "l13", "num": 13, "titulo": "Saúde da mulher", "intro": "Cólicas, TPM, menopausa, ferro em baixa — o corpo da mulher tem ciclos, e cada fase pede um cuidado diferente. As receitas deste capítulo são apoios tradicionais para os desconfortos do ciclo. CÓLICA MUITO FORTE, SANGRAMENTO INTENSO OU DOR QUE IMPEDE A ROTINA NÃO É \"NORMAL\" — é assunto de ginecologista. Endometriose, miomas e outras condições existem e têm tratamento.", "info": "img/cap/l13.webp", "capa": "img/rc/r098.webp", "receitas": [{"n": 98, "titulo": "Chá de canela e gengibre para cólicas", "serve": "Ambos têm ação anti-inflamatória e relaxante sobre a musculatura — há estudos mostrando redução da dor menstrual.", "ing": ["1 pau de canela", "3 fatias de gengibre fresco", "300 ml de água", "Mel a gosto"], "preparo": "Ferva tudo por 8 minutos. Coe e adoce.", "uso": "2 a 3 xícaras por dia, começando 1 ou 2 dias antes da menstruação e durante os primeiros dias.", "dica": "Começar antes da dor chegar faz muita diferença.", "cautela": "Fluxo muito intenso: o gengibre e a canela podem aumentar levemente o sangramento em algumas mulheres. Observe.", "tags": ["Cólica menstrual"]}, {"n": 99, "titulo": "Bolsa de água quente com óleo de lavanda", "serve": "O calor local relaxa a musculatura uterina — é um dos alívios mais eficazes e mais subestimados para a cólica.", "ing": ["1 bolsa de água quente", "2 gotas de óleo essencial de lavanda numa colher de óleo vegetal"], "preparo": "Massageie o baixo-ventre com o óleo diluído e aplique a bolsa por cima.", "uso": "20 minutos, quantas vezes precisar.", "cautela": "Nunca escaldante, nunca direto na pele nua sem proteção.", "tags": ["Cólica menstrual"]}, {"n": 100, "titulo": "Chá de framboesa (folhas)", "serve": "A folha de framboesa é tradicionalmente usada como tônico uterino, no apoio ao ciclo.", "ing": ["1 colher de chá de folhas secas de framboesa", "250 ml de água"], "preparo": "Ferva, desligue, infusione 10 minutos, coe.", "uso": "1 a 2 xícaras por dia, exceto durante a menstruação.", "cautela": "Gravidez: só sob orientação médica (é usada tradicionalmente no fim da gestação, mas não por conta própria).", "tags": ["Cólica menstrual"]}, {"n": 101, "titulo": "Suco de ferro (beterraba, laranja e salsa)", "serve": "Ferro vegetal + vitamina C, que é o que permite ao corpo absorver esse ferro. Apoio para quem tem tendência à anemia.", "ing": ["1 beterraba pequena", "Suco de 2 laranjas", "1 punhado de salsa", "200 ml de água"], "preparo": "Bata tudo.", "uso": "1 copo, 3 a 4 vezes por semana.", "dica": "Não tome café ou chá preto junto ou até 1 hora depois — eles bloqueiam a absorção do ferro. A vitamina C faz o contrário: multiplica.", "cautela": "Anemia diagnosticada precisa de tratamento médico e suplementação — suco não resolve. Gravidez: cuidado com a salsa."}, {"n": 102, "titulo": "Chá de sálvia para os fogachos da menopausa", "serve": "A sálvia é a erva mais tradicionalmente usada no apoio aos calores e à sudorese da menopausa.", "ing": ["1 colher de chá de folhas secas de sálvia", "250 ml de água"], "preparo": "Ferva, desligue, tampe 8 minutos, coe.", "uso": "1 xícara por dia, por até 4 semanas.", "cautela": "Não use por longos períodos (contém tujona, que em excesso é neurotóxica). Epilepsia, gravidez, amamentação: não use. Câncer de mama hormônio-dependente: converse com o médico.", "tags": ["Fogachos (menopausa)"]}, {"n": 103, "titulo": "Linhaça diária (fitoestrógenos)", "serve": "A linhaça é a maior fonte alimentar de lignanas, fitoestrógenos que apoiam o equilíbrio hormonal na transição da menopausa.", "ing": ["1 a 2 colheres de sopa de linhaça moída na hora"], "preparo": "Moa e junte ao iogurte, à salada, à sopa ou à vitamina.", "uso": "Todos os dias.", "cautela": "Câncer hormônio-dependente: converse com o médico. Beba bastante água.", "tags": ["Fogachos (menopausa)"]}]}, {"id": "l14", "num": 14, "titulo": "Memória, foco e cérebro", "intro": "O cérebro é um órgão guloso: consome cerca de 20% de toda a energia do corpo. E é feito, em boa parte, de gordura. O que o protege ao longo dos anos: gordura boa (ômega-3), antioxidantes, açúcar no sangue estável, sono, movimento — e uso. Cérebro que não é desafiado enferruja. Estas receitas apoiam a nutrição do cérebro. O resto é hábito.", "info": "img/cap/l14.webp", "capa": "img/rc/r104.webp", "receitas": [{"n": 104, "titulo": "Chá de ginkgo biloba", "serve": "A planta mais estudada no apoio à circulação cerebral e à memória.", "ing": ["1 colher de chá de folhas secas de ginkgo", "250 ml de água"], "preparo": "Ferva, desligue, infusione 10 minutos, coe.", "uso": "1 xícara por dia, pela manhã, em ciclos de algumas semanas.", "cautela": "Aumenta o risco de sangramento — não combine com anticoagulantes ou aspirina, e suspenda 2 semanas antes de qualquer cirurgia. Epilepsia: evite. Esta é uma das plantas com mais interações medicamentosas: fale com o médico.", "tags": ["Memória / concentração"]}, {"n": 105, "titulo": "Chá de alecrim para o foco", "serve": "O alecrim é tradicionalmente a \"erva da memória\" — e há estudos ligando seu aroma à melhora da atenção.", "ing": ["1 ramo de alecrim", "250 ml de água"], "preparo": "Ferva, desligue, tampe 8 minutos, coe.", "uso": "1 xícara pela manhã ou antes de uma tarefa que exige concentração.", "cautela": "Pressão alta, epilepsia, gravidez: modere ou evite.", "tags": ["Memória / concentração"]}, {"n": 106, "titulo": "Vitamina de mirtilo, nozes e cacau", "serve": "As três estrelas do cérebro numa taça: antioxidantes do mirtilo, ômega-3 das nozes, flavonoides do cacau.", "ing": ["1 xícara de mirtilos (ou uvas roxas)", "1 punhado de nozes", "1 colher de sopa de cacau em pó", "200 ml de leite ou bebida vegetal", "1 banana"], "preparo": "Bata tudo.", "uso": "1 copo, 3 a 4 vezes por semana.", "cautela": "Cacau contém cafeína em pequena quantidade: evite à noite se for sensível.", "tags": ["Memória / concentração"]}, {"n": 107, "titulo": "Sardinha no pão integral (ômega-3 barato)", "serve": "O cérebro é feito de gordura — e o DHA do peixe é a gordura de que ele mais precisa. Sardinha é a forma mais barata de obtê-la.", "ing": ["1 lata de sardinha em azeite, escorrida", "2 fatias de pão integral", "Limão, salsa, azeite"], "preparo": "Amasse a sardinha com limão e salsa, espalhe no pão.", "uso": "2 a 3 vezes por semana, no almoço ou lanche.", "dica": "Coma as espinhas: são macias e cheias de cálcio.", "cautela": "Ácido úrico alto: sardinha é rica em purinas — modere.", "tags": ["Memória / concentração"]}, {"n": 108, "titulo": "Café com cacau e canela (\"café do foco\")", "serve": "Cafeína + flavonoides do cacau: atenção sustentada, sem o pico e a queda brusca do açúcar.", "ing": ["1 xícara de café", "1 colher de chá de cacau em pó 100%", "1 pitada de canela"], "preparo": "Misture bem.", "uso": "1 xícara pela manhã.", "cautela": "Não passe de 3 a 4 cafés por dia. Nunca depois das 16h, se você quer dormir.", "tags": ["Memória / concentração"]}]}, {"id": "l15", "num": 15, "titulo": "As bases: o que toda cozinha natural deve saber fazer", "intro": "Este capítulo é diferente. Não são receitas para um problema específico — são as técnicas-mãe. Aprendendo estas sete, você consegue criar as suas próprias fórmulas. É aqui que você deixa de seguir receitas e começa a entendêlas.", "info": "img/cap/l15.webp", "capa": "img/rc/r109.webp", "receitas": [{"n": 109, "titulo": "Infusão (a técnica das folhas e flores)", "serve": "É a técnica para as partes delicadas da planta: folhas, flores, sementes aromáticas. O calor da água basta; ferver destruiria os óleos.", "fazer": "Ferva a água. Desligue o fogo. Despeje sobre a erva (1 colher de chá por xícara), tampe e espere 5 a 10 minutos. Coe.", "regra": "Tampar não é detalhe: sem tampa, o aroma — que é o remédio — evapora com o vapor.", "usepara": "camomila, hortelã, melissa, tília, erva-doce, chá verde, tomilho, alecrim."}, {"n": 110, "titulo": "Decocção (a técnica das raízes e cascas)", "serve": "Para as partes duras: raízes, cascas, sementes grandes, pedaços lenhosos. Precisam de fogo e tempo para entregar o que têm.", "fazer": "Junte a erva à água fria, leve ao fogo, ferva e mantenha fervendo em fogo baixo por 10 a 20 minutos. Desligue, tampe, espere mais 10. Coe.", "regra": "Raiz e casca não se fazem em infusão: a água quente escorre por fora sem tirar nada de dentro.", "usepara": "gengibre, canela em pau, valeriana, mulungu, ginseng, cardo-mariano, salgueiro."}, {"n": 111, "titulo": "Maceração a frio", "serve": "Para os princípios que o calor destrói — sobretudo as mucilagens (aquele gel protetor) e a vitamina C.", "fazer": "Deixe a erva na água fria, em temperatura ambiente ou na geladeira, por 2 a 12 horas. Coe.", "usepara": "alteia (marshmallow), linhaça, chia, quiabo, semente de psyllium."}, {"n": 112, "titulo": "Xarope caseiro (a base)", "serve": "Um xarope é apenas isto: um princípio ativo + mel ou açúcar, que conserva e acalma a garganta.", "fazer": ["Prepare uma decocção forte da erva (o dobro da erva, metade da água).", "Coe.", "Misture com mel na proporção de 1 parte de líquido para 1 parte de mel.", "Guarde num vidro esterilizado, na geladeira."], "usepara": "tomilho, gengibre, alteia, cebola, sabugueiro.", "duracao": "2 a 3 semanas na geladeira. Se mudar de cheiro, cor ou aparecer bolha: jogue fora."}, {"n": 113, "titulo": "Tintura (extrato em álcool)", "serve": "O álcool extrai princípios que a água não alcança, e conserva por anos.", "fazer": ["Encha um vidro até a metade com a erva seca picada.", "Cubra completamente com vodka ou álcool de cereais (mínimo 40%).", "Feche, etiquete com a data, e deixe num armário escuro por 4 semanas, agitando a cada dois dias.", "Coe num pano fino, espremendo bem. Guarde em vidro escuro."], "uso": "Geralmente 20 a 30 gotas em água, até 3 vezes ao dia — mas a dose depende de cada planta. Pesquise sempre.", "cautela": "Contém álcool: não indicado para crianças, gestantes, ou quem tem histórico de dependência. Nunca faça tintura de plantas que você não tem certeza de identificar."}, {"n": 114, "titulo": "Óleo infusionado", "serve": "Para uso externo (massagem, pele, cabelo): extrai os princípios lipossolúveis das ervas.", "fazer": ["Encha um vidro com a erva completamente seca (erva úmida cria mofo!).", "Cubra com azeite ou óleo de amêndoas.", "Deixe no parapeito da janela, ao sol, por 3 a 4 semanas. Ou: aqueça em banho-maria por 3 horas, em fogo muito baixo.", "Coe."], "usepara": "calêndula (pele irritada), alecrim (cabelo), arnica (só uso externo, nunca ingerir), lavanda.", "cautela": "Erva úmida = mofo = jogar fora tudo. Seque bem."}, {"n": 115, "titulo": "Compressa e cataplasma", "serve": "Levar o remédio direto ao lugar que dói.", "fazer": "- Compressa: prepare um chá forte, molhe um pano limpo, torça e aplique sobre a região (quente para dores musculares e rigidez; fria para inchaço, pancada e febre). Cataplasma: amasse a erva fresca (ou hidrate a seca) até formar uma pasta, coloque entre duas camadas de gaze e aplique sobre a pele.", "usepara": "gengibre (dores), camomila (irritação), argila (inflamação local), couve (dor articular).", "cautela": "Nunca sobre pele ferida ou infeccionada. Sempre teste a temperatura."}]}, {"id": "l16", "num": 16, "titulo": "Dores de cabeça e enxaqueca", "intro": "A maioria das dores de cabeça tem causas banais e resolvíveis: pouca água, pouco sono, muito estresse, muita tela, fome, cafeína a mais — ou a menos. PROCURE UM MÉDICO se a dor for súbita e violenta (\"a pior da minha vida\"), vier com febre, rigidez de nuca, confusão, fraqueza de um lado do corpo ou alteração da visão. Isso não é dor de cabeça comum.", "info": null, "capa": "img/rc/r116.webp", "receitas": [{"n": 116, "titulo": "Chá de gengibre para enxaqueca", "serve": "Há estudos comparando o gengibre a medicamentos de enxaqueca, com resultados promissores — sobretudo se tomado no início da crise.", "ing": ["1 colher de chá de gengibre em pó (ou 4 fatias frescas)", "250 ml de água"], "preparo": "Ferva 8 minutos, coe.", "uso": "Aos primeiros sinais da crise. Até 2 xícaras.", "cautela": "Anticoagulantes: cuidado.", "tags": ["Dor de cabeça", "Enxaqueca"]}, {"n": 117, "titulo": "Compressa fria de hortelã na testa", "serve": "O mentol dá sensação de frio e alivia a dor tensional.", "ing": ["1 chá forte de hortelã, gelado", "1 pano limpo"], "preparo": "Molhe o pano no chá gelado, torça e aplique na testa e nas têmporas.", "uso": "15 minutos, com os olhos fechados, no escuro.", "cautela": "Óleo essencial de hortelã diluído (1 gota em 1 colher de óleo) pode ser massageado nas têmporas — nunca perto dos olhos.", "tags": ["Dor de cabeça"]}, {"n": 118, "titulo": "Água com magnésio (banana, castanha e cacau)", "serve": "A falta de magnésio está associada à enxaqueca. Este batido é rico nele.", "ing": ["1 banana", "1 punhado de castanhas", "1 colher de sopa de cacau", "200 ml de leite ou bebida vegetal"], "preparo": "Bata tudo.", "uso": "1 copo por dia, como prevenção.", "cautela": "Problemas renais: excesso de magnésio é perigoso. Fale com o médico.", "tags": ["Cãibras / dores musculares", "Dor de cabeça"]}, {"n": 119, "titulo": "Café forte com limão (para a crise)", "serve": "A cafeína contrai os vasos dilatados da enxaqueca — é, aliás, ingrediente de muitos analgésicos de farmácia.", "ing": ["1 xícara de café forte", "Suco de ½ limão"], "preparo": "Misture e beba de uma vez.", "uso": "No início da crise. No máximo 1 vez.", "cautela": "Uso frequente causa o efeito contrário: a cefaleia de rebote. Não faça disso um hábito.", "tags": ["Dor de cabeça", "Enxaqueca"]}, {"n": 120, "titulo": "Chá de matricária (tanaceto)", "serve": "Uma das poucas plantas com estudos na prevenção da enxaqueca (não na crise).", "ing": ["1 colher de chá de folhas secas", "250 ml de água"], "preparo": "Infusione 10 minutos, coe.", "uso": "1 xícara por dia, de forma contínua, por 2 a 3 meses — o efeito é preventivo, não imediato.", "cautela": "Grávidas: não use. Alérgicos à família da margarida: evite. Interrompa gradualmente (parar de repente pode dar dor de rebote).", "tags": ["Enxaqueca"]}, {"n": 121, "titulo": "Ritual dos 3 gestos (água, escuro, respiração)", "serve": "O tratamento não farmacológico mais eficaz — e o mais ignorado.", "preparo": ["Beba 2 copos grandes de água (a desidratação é a causa nº 1).", "Deite num quarto escuro e silencioso.", "Respire: inspire em 4 tempos, expire em 6 a 8 tempos, por 5 minutos."], "uso": "Ao primeiro sinal de dor.", "cautela": "Nenhuma. Funciona mais do que se imagina.", "tags": ["Dor de cabeça"]}]}, {"id": "l17", "num": 17, "titulo": "Circulação, varizes e pernas pesadas", "intro": "Sangue que sobe mal, pernas que incham no fim do dia, veias que aparecem. É comum — e há muito o que fazer antes de qualquer procedimento. O básico: mover as pernas (a panturrilha é a \"segunda bomba\" do corpo), não ficar horas parado, elevar as pernas, e comer o que fortalece as veias — flavonoides.", "info": null, "capa": "img/rc/r122.webp", "receitas": [{"n": 122, "titulo": "Chá de castanha-da-índia", "serve": "A planta mais estudada para insuficiência venosa: fortalece a parede das veias e reduz o inchaço.", "ing": ["1 colher de chá de casca seca de castanha-da-índia", "250 ml de água"], "preparo": "Ferva 10 minutos, coe.", "uso": "1 xícara por dia, por até 8 semanas.", "cautela": "A semente crua é tóxica — use apenas preparados adequados. Problemas renais ou hepáticos, gravidez, anticoagulantes: não use sem falar com o médico.", "tags": ["Pernas pesadas / varizes"]}, {"n": 123, "titulo": "Suco de frutas vermelhas (flavonoides)", "serve": "Antocianinas fortalecem os capilares e as veias.", "ing": ["1 xícara de frutas vermelhas (amora, mirtilo, morango)", "200 ml de água", "Suco de ½ limão"], "preparo": "Bata tudo.", "uso": "1 copo por dia.", "cautela": "Nenhuma relevante.", "tags": ["Pernas pesadas / varizes"]}, {"n": 124, "titulo": "Banho de contraste nas pernas", "serve": "Alterna quente e frio: os vasos dilatam e contraem, e isso \"bombeia\" o sangue de volta. Um dos alívios mais eficazes para pernas pesadas.", "preparo": "Na ducha, jogue água morna nas pernas por 2 minutos, depois água fria por 30 segundos. Repita 3 vezes. Termine sempre no frio.", "uso": "À noite, todos os dias.", "cautela": "Problemas cardíacos graves ou neuropatia diabética: fale com o médico.", "tags": ["Pernas pesadas / varizes"]}, {"n": 125, "titulo": "Massagem com óleo de hortelã e alecrim", "serve": "Alivia o peso e refresca. Massagear de baixo para cima empurra o sangue na direção certa.", "ing": ["2 colheres de sopa de óleo vegetal (amêndoas, coco)", "3 gotas de óleo essencial de hortelã", "2 gotas de óleo essencial de alecrim"], "preparo": "Misture.", "uso": "Massageie as pernas do tornozelo em direção ao joelho e à coxa, à noite.", "cautela": "Varizes muito inflamadas ou trombose: não massageie. Procure um médico.", "tags": ["Pernas pesadas / varizes"]}, {"n": 126, "titulo": "Chá de ginkgo com hibisco (circulação)", "serve": "Apoio à microcirculação e à pressão.", "ing": ["½ colher de chá de ginkgo seco", "½ colher de chá de hibisco", "250 ml de água"], "preparo": "Infusione 10 minutos, coe.", "uso": "1 xícara por dia, por até 1 mês.", "cautela": "Ginkgo aumenta risco de sangramento — não combine com anticoagulantes. Pressão baixa: cuidado com o hibisco."}]}, {"id": "l18", "num": 18, "titulo": "Alergias, rinite e sinusite", "intro": "O nariz que não desentope. O espirro que não acaba. Os olhos que coçam. Quem tem, sabe. Estas receitas ALIVIAM. Não curam a alergia — a alergia é uma tendência do seu sistema imune, e ela não vai embora. O que muda é o quanto ela atrapalha. O MAIS IMPORTANTE NÃO É UMA RECEITA: É REDUZIR A EXPOSIÇÃO. Ácaro, poeira, mofo, pelo de animal, fumaça. Colchão encapado, casa arejada, sem tapete e sem cortina pesada no quarto vale mais que qualquer chá.", "info": null, "capa": "img/rc/r127.webp", "receitas": [{"n": 127, "titulo": "Lavagem nasal diária (o pilar)", "serve": "A medida com melhor evidência para rinite e sinusite. Simples, barata, segura.", "ing": ["250 ml de água fervida e resfriada (ou soro fisiológico)", "½ colher de chá de sal", "1 pitada de bicarbonato"], "preparo": "Dissolva no líquido morno.", "uso": "Lave cada narina, 1 a 2 vezes ao dia, todos os dias. É um hábito, como escovar os dentes.", "cautela": "Nunca use água da torneira direto. Ferva sempre.", "tags": ["Congestão nasal", "Rinite / alergia", "Sinusite"]}, {"n": 128, "titulo": "Chá de urtiga", "serve": "A urtiga é tradicionalmente usada como anti-histamínico natural — há estudos preliminares no apoio à rinite alérgica.", "ing": ["1 colher de chá de folhas secas de urtiga", "250 ml de água"], "preparo": "Infusione 10 minutos, coe.", "uso": "2 xícaras por dia, na estação das alergias.", "cautela": "Diurético: cuidado se toma diuréticos ou remédio de pressão. Gravidez: evite.", "tags": ["Rinite / alergia"]}, {"n": 129, "titulo": "Mel local (da sua região)", "serve": "A ideia tradicional é que o mel produzido perto de você contém traços do pólen local, expondo o corpo em pequenas doses. A evidência é fraca — mas o mel acalma a garganta de qualquer forma.", "ing": ["1 colher de chá de mel local, cru"], "uso": "1 colher por dia.", "cautela": "Menores de 1 ano: não. E seja honesto: isto é tradição, não é tratamento comprovado."}, {"n": 130, "titulo": "Inalação de vapor com camomila", "serve": "Descongestiona sem irritar — mais suave que o eucalipto.", "ing": ["1 litro de água fervente", "1 punhado de flores de camomila"], "preparo": "Despeje numa bacia, cubra a cabeça com uma toalha e inale 10 minutos.", "uso": "1 a 2 vezes ao dia na crise.", "cautela": "Alérgicos à família da margarida: evite (irônico, mas real).", "tags": ["Congestão nasal", "Rinite / alergia", "Sinusite"]}, {"n": 131, "titulo": "Suco de quercetina (cebola roxa, maçã e alcaparra)", "serve": "A quercetina é o flavonoide mais estudado no apoio à estabilização das células que liberam histamina.", "ing": ["¼ de cebola roxa", "1 maçã com casca", "Suco de 1 limão", "200 ml de água"], "preparo": "Bata e coe.", "uso": "1 copo por dia na estação das alergias.", "dica": "Sim, tem cebola. Não, não fica ruim — a maçã e o limão dominam.", "cautela": "Refluxo: pode incomodar.", "tags": ["Rinite / alergia"]}]}, {"id": "l19", "num": 19, "titulo": "Boca, dentes e gengivas", "intro": "A boca é a porta do corpo — e uma gengiva inflamada crônica está associada, hoje sabemos, a problemas de coração. Nada aqui substitui escovar, usar fio dental e ir ao dentista. Mas ajuda.", "info": null, "capa": "img/rc/r132.webp", "receitas": [{"n": 132, "titulo": "Bochecho de água salgada", "serve": "Alivia gengiva inflamada, afta e garganta irritada. Simples e eficaz.", "ing": ["1 copo de água morna", "½ colher de chá de sal"], "uso": "Bocheche 30 segundos, 2 a 3 vezes ao dia. Não engula.", "cautela": "Nenhuma.", "tags": ["Dor de garganta", "Gengiva inflamada"]}, {"n": 133, "titulo": "Enxaguante de sálvia e cravo", "serve": "Sálvia é adstringente e o cravo é um analgésico natural (contém eugenol — usado em odontologia).", "ing": ["1 colher de chá de sálvia seca", "3 cravos-da-índia", "250 ml de água"], "preparo": "Ferva 10 minutos, coe, deixe esfriar.", "uso": "Bocheche 2 vezes ao dia. Guarde na geladeira por 2 dias.", "cautela": "Não engula em quantidade (a sálvia contém tujona). Gravidez: evite.", "tags": ["Gengiva inflamada"]}, {"n": 134, "titulo": "Óleo de cravo para dor de dente", "serve": "O analgésico dentário mais antigo do mundo. O eugenol adormece a dor.", "ing": ["1 gota de óleo essencial de cravo", "1 colher de chá de óleo vegetal (coco, azeite)", "1 cotonete"], "preparo": "Dilua a gota no óleo.", "uso": "Aplique com o cotonete no dente dolorido (não na gengiva).", "cautela": "Isto é um paliativo, não um tratamento. Dor de dente = ir ao dentista. Não use puro (queima a mucosa). Crianças: não.", "tags": ["Dor de dente"]}, {"n": 135, "titulo": "Oil pulling (bochecho de óleo de coco)", "serve": "Prática ayurvédica: bochechar óleo reduz bactérias e melhora o hálito.", "ing": ["1 colher de sopa de óleo de coco"], "uso": "Bocheche por 10 a 15 minutos, em jejum. Cuspa no lixo (não na pia — entope). Escove os dentes depois.", "cautela": "Não engula. Não substitui a escovação."}, {"n": 136, "titulo": "Pasta de bicarbonato e cúrcuma (clareamento suave)", "serve": "Limpeza leve e ação antibacteriana.", "ing": ["1 colher de chá de bicarbonato", "1 pitada de cúrcuma", "Gotas de água"], "preparo": "Forme uma pasta.", "uso": "No máximo 1 vez por semana.", "cautela": "O bicarbonato é abrasivo — usar todo dia desgasta o esmalte, e esmalte não volta. Uma vez por semana, no máximo."}]}, {"id": "l20", "num": 20, "titulo": "Saúde do homem", "intro": "Homem vai pouco ao médico. É um fato, e custa caro. Este capítulo é curto, e a mensagem mais importante dele não é uma receita: A PARTIR DOS 50 ANOS (OU DOS 45, COM HISTÓRICO FAMILIAR), O EXAME DE PRÓSTATA É INEGOCIÁVEL. Nenhum chá substitui isso. Dito isso, há apoios reais.", "info": null, "capa": "img/rc/r137.webp", "receitas": [{"n": 137, "titulo": "Chá de saw palmetto", "serve": "A planta mais estudada no apoio aos sintomas urinários do aumento benigno da próstata.", "ing": ["1 colher de chá de frutos secos", "250 ml de água"], "preparo": "Ferva 10 minutos, coe.", "uso": "1 xícara por dia, por alguns meses.", "cautela": "Não trata câncer de próstata e pode mascarar sintomas. Faça os exames. Interfere com anticoagulantes e hormônios.", "tags": ["Próstata"]}, {"n": 138, "titulo": "Sementes de abóbora (zinco)", "serve": "Ricas em zinco, o mineral mais associado à saúde da próstata e à testosterona.", "ing": ["1 punhado de sementes de abóbora cruas"], "uso": "1 punhado por dia, como lanche.", "cautela": "Nenhuma. Uma das receitas mais simples e úteis do livro.", "tags": ["Próstata"]}, {"n": 139, "titulo": "Tomate cozido com azeite (licopeno)", "serve": "O licopeno do tomate está associado à saúde da próstata — e ele só é bem absorvido cozido e com gordura.", "ing": ["4 tomates maduros", "2 colheres de sopa de azeite", "Alho, manjericão, sal"], "preparo": "Cozinhe os tomates com o azeite e o alho por 20 minutos.", "uso": "3 a 4 vezes por semana, como molho.", "dica": "Tomate cru tem menos licopeno disponível que o molho cozido. Aqui, cozinhar melhora.", "cautela": "Refluxo: o tomate é ácido.", "tags": ["Próstata"]}, {"n": 140, "titulo": "Chá de urtiga (raiz) para a próstata", "serve": "A raiz de urtiga é tradicionalmente combinada ao saw palmetto no apoio urinário.", "ing": ["1 colher de chá de raiz seca de urtiga", "250 ml de água"], "preparo": "Ferva 10 minutos, coe.", "uso": "1 xícara por dia.", "cautela": "Diuréticos e remédios de pressão: fale com o médico.", "tags": ["Próstata"]}]}, {"id": "l21", "num": 21, "titulo": "Crianças (com muito cuidado)", "intro": "Este é o capítulo mais delicado do livro, e o que exige mais respeito. CRIANÇA NÃO É ADULTO PEQUENO. O fígado e os rins de uma criança processam as substâncias de forma diferente. Doses de adulto podem ser perigosas. E há ervas que são simplesmente proibidas para elas. REGRAS ABSOLUTAS: - Mel: nunca antes de 1 ano (botulismo infantil — risco real e grave). - Nada de óleos essenciais (eucalipto, hortelã, cânfora) em bebês e crianças pequenas: risco de espasmo respiratório. - Nunca aspirina nem salgueiro em crianças (síndrome de Reye). - Febre em bebê de menos de 3 meses: pronto-socorro. Agora. - Diante de qualquer dúvida: pediatra. O que sobra é pouco — e é o que basta.", "info": null, "capa": "img/rc/r141.webp", "receitas": [{"n": 141, "titulo": "Chá de camomila muito fraco (a partir de 6 meses)", "serve": "Acalma cólicas e agitação leve.", "ing": ["1 pitada de camomila", "200 ml de água"], "preparo": "Infusione 5 minutos e coe muito bem. Deve ficar quase transparente.", "uso": "Poucas colheres, morno. Pergunte ao pediatra antes.", "cautela": "Não substitui leite nem água. Excesso de chá em bebê pode tirar o apetite e desequilibrar o sódio."}, {"n": 142, "titulo": "Soro caseiro de reidratação", "serve": "Em diarreia ou vômito, o risco real não é o germe — é a desidratação. Esta receita salva vidas, literalmente, e é recomendada pela OMS.", "ing": ["1 litro de água fervida e resfriada", "1 colher de chá rasa de sal", "2 colheres de sopa de açúcar"], "preparo": "Dissolva bem. As medidas são exatas — não improvise.", "uso": "Em pequenos goles, com frequência, ao longo do dia.", "cautela": "Procure o médico se: a criança estiver muito abatida, sem urinar por 6 horas, com boca seca, olhos fundos, ou não parar de vomitar. O soro é a ponte até o atendimento, não o substituto dele.", "tags": ["Diarreia (reidratação)"]}, {"n": 143, "titulo": "Mel para tosse (só acima de 1 ano)", "serve": "Há estudos mostrando que o mel alivia a tosse noturna em crianças melhor que xaropes de farmácia.", "ing": ["½ a 1 colher de chá de mel"], "uso": "Antes de dormir, puro ou num pouco de água morna.", "cautela": "NUNCA antes de 1 ano de idade. Sem exceção."}, {"n": 144, "titulo": "Banho morno para febre", "serve": "Conforto e redução suave da temperatura.", "preparo": "Banho com água morna (não fria!), por 10 a 15 minutos.", "cautela": "Nunca água fria nem álcool — causa tremor, que aumenta a temperatura, e o álcool é absorvido pela pele. Febre alta, persistente, ou em bebê pequeno: médico."}, {"n": 145, "titulo": "Vaporizador de água (nariz entupido)", "serve": "Umidifica o ar e afina o muco, sem nenhum risco.", "preparo": "Ligue um umidificador, ou deixe uma bacia de água quente no quarto (longe do alcance da criança). Um banho quente de vapor no banheiro também serve.", "cautela": "Sem óleos essenciais. Só vapor de água. E cuidado com queimaduras.", "tags": ["Congestão nasal"]}, {"n": 146, "titulo": "Soro fisiológico no nariz do bebê", "serve": "O jeito seguro e recomendado de desentupir o nariz de um bebê.", "ing": ["Soro fisiológico 0,9% (de farmácia)"], "uso": "Algumas gotas em cada narina, antes das mamadas e do sono. Aspire suavemente se necessário.", "cautela": "Use soro de farmácia, estéril. Não improvise com água salgada caseira em bebês.", "tags": ["Congestão nasal"]}]}, {"id": "l22", "num": 22, "titulo": "Pele ferida: cortes, queimaduras e picadas", "intro": "Uso externo. Nada aqui se bebe. VÁ AO MÉDICO SE: o corte for profundo ou não parar de sangrar; a queimadura formar bolhas grandes, for em rosto/mãos/genitais, ou for maior que a palma da mão; houver pus, vermelhidão que se espalha, ou febre; a picada causar falta de ar, inchaço na boca ou tontura (isso é emergência — pronto-socorro imediatamente).", "info": null, "capa": "img/rc/r147.webp", "receitas": [{"n": 147, "titulo": "Água fria corrente para queimadura", "serve": "O primeiro socorro correto, e o que mais evita sequelas.", "preparo": "Água corrente, fria (não gelada) sobre a queimadura, por 20 minutos.", "cautela": "Nunca manteiga, pasta de dente, borra de café, gelo ou pomada caseira numa queimadura. Isso piora, contamina e dificulta o atendimento. Só água.", "tags": ["Queimadura"]}, {"n": 148, "titulo": "Gel de babosa (aloe vera)", "serve": "Um dos poucos preparos caseiros com boa evidência: acalma queimaduras leves de sol e irritações.", "ing": ["1 folha de babosa"], "preparo": "Corte a folha, deixe escorrer o látex amarelo (que irrita) por 10 minutos, e raspe o gel transparente de dentro.", "uso": "Aplique sobre a pele limpa, 2 a 3 vezes ao dia.", "cautela": "Só uso externo — não beba. Não use em feridas abertas ou profundas.", "tags": ["Cicatrização", "Pele seca / irritada", "Queimadura"]}, {"n": 149, "titulo": "Pomada de calêndula", "serve": "A calêndula é a erva da pele por excelência: apoia a cicatrização e acalma a irritação.", "ing": ["4 colheres de sopa de óleo infusionado de calêndula (ver receita 114)", "1 colher de sopa de cera de abelha"], "preparo": "Derreta a cera no óleo em banho-maria, mexa e despeje num potinho. Deixe solidificar.", "uso": "Sobre pele irritada, ressecada, assaduras.", "cautela": "Não use em feridas infeccionadas. Alérgicos à família da margarida: teste antes.", "tags": ["Cicatrização", "Pele seca / irritada"]}, {"n": 150, "titulo": "Compressa fria de camomila para picadas", "serve": "Alivia a coceira e o inchaço da picada de inseto.", "ing": ["Chá de camomila forte, gelado"], "uso": "Compressa sobre a picada por 10 minutos.", "cautela": "Falta de ar, inchaço de lábios/língua, tontura após picada = alergia grave. Pronto-socorro AGORA.", "tags": ["Coceira / picada de inseto"]}, {"n": 151, "titulo": "Pasta de bicarbonato para coceira", "serve": "Neutraliza a acidez da picada e alivia a coceira.", "ing": ["1 colher de chá de bicarbonato", "Gotas de água"], "preparo": "Forme uma pasta.", "uso": "Aplique na picada, deixe secar, enxágue.", "cautela": "Não use em pele ferida.", "tags": ["Coceira / picada de inseto"]}, {"n": 152, "titulo": "Compressa de arnica para pancadas (roxos)", "serve": "A arnica é a planta clássica para hematomas e contusões.", "ing": ["Tintura de arnica diluída (1 parte em 3 de água), ou pomada pronta"], "uso": "Compressa sobre o roxo, 2 vezes ao dia.", "cautela": "A arnica é para uso EXTERNO apenas. Nunca ingerir — é tóxica. Nunca sobre pele ferida ou cortada.", "tags": ["Hematomas (roxos)"]}]}, {"id": "l23", "num": 23, "titulo": "Ressaca, excessos e recuperação", "intro": "Todos exageram, de vez em quando. Este capítulo é o do dia seguinte. A ressaca é, em boa parte, DESIDRATAÇÃO somada à inflamação e à falta de vitaminas do complexo B. A única cura verdadeira é o tempo — mas dá para atravessar melhor.", "info": null, "capa": "img/rc/r153.webp", "receitas": [{"n": 153, "titulo": "Reidratação de ressaca", "serve": "Repõe água e eletrólitos — é 80% do problema.", "ing": ["500 ml de água de coco", "Suco de 1 limão", "1 pitada de sal", "1 colher de chá de mel"], "preparo": "Misture.", "uso": "Beba devagar, ao acordar.", "cautela": "Nenhuma. Água é o remédio.", "tags": ["Ressaca"]}, {"n": 154, "titulo": "Chá de gengibre e hortelã para o enjoo", "serve": "Acalma o estômago revirado.", "ing": ["3 fatias de gengibre", "1 punhado de hortelã", "250 ml de água"], "preparo": "Ferva o gengibre 5 minutos, desligue, junte a hortelã e tampe 5 minutos.", "uso": "Em pequenos goles.", "cautela": "Refluxo: pule a hortelã.", "tags": ["Enjoo / náusea", "Ressaca"]}, {"n": 155, "titulo": "Sopa quente de legumes com ovo", "serve": "Repõe sódio, potássio e aminoácidos. O corpo pede exatamente isso.", "ing": ["500 ml de caldo de legumes quente", "1 ovo", "Salsa"], "preparo": "Aqueça o caldo, junte o ovo batido mexendo (fica em fios), salpique salsa.", "uso": "Almoço do dia seguinte.", "cautela": "Nenhuma.", "tags": ["Ressaca"]}, {"n": 156, "titulo": "Chá de cardo-mariano (apoio ao fígado)", "serve": "Apoia o fígado que trabalhou demais.", "ing": ["1 colher de chá de sementes amassadas", "250 ml de água"], "preparo": "Infusione 15 minutos, coe.", "uso": "1 xícara no dia seguinte.", "cautela": "Isto não é licença para beber. Se a ressaca é frequente, o problema não é a ressaca.", "tags": ["Ressaca"]}]}, {"id": "l24", "num": 24, "titulo": "As bebidas do dia a dia", "intro": "Nem tudo precisa ser remédio. Algumas destas você vai fazer simplesmente porque são boas — e, de quebra, fazem bem.", "info": null, "capa": "img/rc/r157.webp", "receitas": [{"n": 157, "titulo": "Chá de hortelã com limão (o refrescante)", "ing": ["1 punhado de hortelã", "250 ml de água", "suco de ½ limão", "mel"], "preparo": "Infusione 7 minutos, coe, junte limão e mel.", "uso": "Quente no inverno, gelado no verão. Sempre.", "cautela": "Refluxo: modere a hortelã."}, {"n": 158, "titulo": "Chá de erva-mate gelado com limão", "ing": ["1 colher de sopa de erva-mate", "500 ml de água", "limão", "hortelã"], "preparo": "Infusione 5 minutos, coe, gele.", "uso": "No lugar do refrigerante.", "cautela": "Contém cafeína. Evite à noite."}, {"n": 159, "titulo": "Chá de rooibos (sem cafeína)", "ing": ["1 colher de chá de rooibos", "250 ml de água"], "preparo": "Infusione 7 minutos.", "uso": "À noite, quando quer o ritual do chá sem a cafeína.", "cautela": "Nenhuma. Pode até para crianças (fraco)."}, {"n": 160, "titulo": "Limonada de gengibre sem açúcar", "ing": ["suco de 2 limões", "1 pedaço de gengibre", "1 litro de água", "adoçante natural a gosto"], "preparo": "Bata o gengibre com um pouco de água, coe, junte o resto.", "uso": "Ao longo do dia, no verão.", "cautela": "Enxágue a boca (esmalte)."}, {"n": 161, "titulo": "Chá de canela e maçã (o aconchego)", "ing": ["1 maçã em cubos", "1 pau de canela", "500 ml de água"], "preparo": "Ferva 10 minutos, coe.", "uso": "Nas noites frias, no lugar da sobremesa.", "cautela": "Nenhuma."}, {"n": 162, "titulo": "Café de especiarias (cardamomo e canela)", "ing": ["café", "1 cardamomo amassado", "1 pitada de canela"], "preparo": "Junte as especiarias ao pó antes de passar.", "uso": "Pela manhã.", "cautela": "Modere no café."}]}, {"id": "l25", "num": 25, "titulo": "Temperos e conservas medicinais", "intro": "Estes são os preparos que ficam na sua despensa e trabalham por você todos os dias, sem que você perceba. É aqui que a saúde deixa de ser um esforço e vira um hábito.", "info": null, "capa": "img/rc/r163.webp", "receitas": [{"n": 163, "titulo": "Alho em conserva no azeite", "serve": "Alho sempre à mão + azeite aromatizado. Dois remédios num vidro só.", "ing": ["1 cabeça de alho descascada", "Azeite extravirgem suficiente para cobrir", "1 ramo de alecrim"], "preparo": "Coloque tudo num vidro esterilizado, cobrindo completamente o alho com o azeite. Feche.", "uso": "Na salada, no pão, no refogado.", "cautela": "⚠️ IMPORTANTE: guarde SEMPRE na geladeira e use em até 1 semana. Alho cru no óleo em temperatura ambiente pode desenvolver a toxina do botulismo. Isto é sério."}, {"n": 164, "titulo": "Sal de ervas (menos sódio)", "serve": "Reduz o sal em até metade, sem perder o sabor.", "ing": ["1 parte de sal", "1 parte de alecrim seco", "1 parte de orégano", "1 parte de manjericão seco", "½ parte de alho em pó"], "preparo": "Bata tudo no liquidificador e guarde num pote.", "uso": "No lugar do sal comum.", "cautela": "Ainda contém sal — não é livre, é reduzido."}, {"n": 165, "titulo": "Mel de gengibre e limão (pote da despensa)", "serve": "O xarope de emergência, sempre pronto na geladeira.", "ing": ["1 pote de mel", "1 pedaço grande de gengibre em fatias finas", "1 limão em rodelas finas"], "preparo": "Alterne camadas num vidro, cobrindo tudo com mel. Guarde na geladeira.", "uso": "1 colher de chá ao primeiro sinal de garganta arranhando. Ou 1 colher no chá.", "dica": "Dura 2 meses na geladeira e fica melhor com o tempo.", "cautela": "Menores de 1 ano: não."}, {"n": 166, "titulo": "Vinagre dos quatro ladrões", "serve": "Receita medieval lendária (dizem que protegia os ladrões que saqueavam casas durante a peste). Aromático, antimicrobiano, ótimo tempero.", "ing": ["500 ml de vinagre de maçã", "1 colher de sopa de cada: alecrim, tomilho, sálvia, lavanda", "3 dentes de alho"], "preparo": "Junte tudo num vidro, feche e deixe 3 a 4 semanas num armário escuro, agitando de vez em quando. Coe.", "uso": "Como tempero de salada, ou 1 colher diluída em água.", "cautela": "Sempre diluído para beber. Gastrite: evite."}, {"n": 167, "titulo": "Azeite de pimenta e alecrim", "serve": "A capsaicina da pimenta tem ação anti-inflamatória e estimula o metabolismo.", "ing": ["250 ml de azeite", "2 pimentas secas", "2 ramos de alecrim bem secos"], "preparo": "Junte tudo num vidro e deixe 2 semanas.", "uso": "Sobre a comida pronta.", "cautela": "Ervas secas, não frescas (frescas + óleo = risco de botulismo). Gastrite: evite a pimenta."}, {"n": 168, "titulo": "Chucrute caseiro (repolho fermentado)", "serve": "Probiótico vivo, feito de dois ingredientes. Um dos alimentos mais saudáveis que existem — e um dos mais baratos.", "ing": ["1 repolho", "1 colher de sopa de sal (cerca de 2% do peso do repolho)"], "preparo": "Fatie o repolho fino, misture com o sal e massageie por 10 minutos até soltar bastante água. Comprima tudo num vidro, garantindo que o líquido cubra completamente o repolho. Ponha um peso em cima. Deixe fora da geladeira, coberto com um pano, por 5 a 14 dias. Depois, geladeira.", "uso": "1 colher de sopa por dia, como acompanhamento.", "dica": "O repolho tem que ficar SUBMERSO. O que fica exposto ao ar, mofa.", "cautela": "Se mofar (mofo preto/verde/peludo), jogue fora tudo. Cheiro azedo é normal; cheiro podre não é. Hipertensos: é salgado, modere."}]}]};
window.SINTOMAS=["Ansiedade", "Azia / gastrite", "Cabelo (queda, fraqueza)", "Cansaço / falta de energia", "Cicatrização", "Coceira / picada de inseto", "Colesterol alto", "Congestão nasal", "Constipação (intestino preso)", "Cãibras / dores musculares", "Cólica menstrual", "Diarreia (reidratação)", "Dor de cabeça", "Dor de dente", "Dor de garganta", "Dor nas articulações", "Enjoo / náusea", "Enxaqueca", "Fogachos (menopausa)", "Gases", "Gengiva inflamada", "Glicemia alta", "Hematomas (roxos)", "Imunidade baixa", "Inchaço / retenção", "Infecção urinária (prevenção)", "Inflamação crônica", "Insônia", "Memória / concentração", "Pele oleosa / acne", "Pele seca / irritada", "Pernas pesadas / varizes", "Pressão alta", "Próstata", "Queimadura", "Resfriado / gripe", "Ressaca", "Rinite / alergia", "Sinusite", "Sono ruim", "Tosse com catarro", "Tosse seca", "Vontade de comer / compulsão"];
window.EXTRAS=[{"id": "x-comece", "titulo": "Comece por aqui", "sub": "Prefácio, como usar e a despensa da natureza", "capa": "img/rc/r163.webp", "banner": "img/r/r163.webp", "itens": [{"t": "h", "x": "Prefácio"}, {"t": "p", "x": "Existe um saber que não nasceu em laboratório."}, {"t": "p", "x": "Nasceu na cozinha. Na horta. No quintal. Nasceu de mulheres e homens que, muito antes de existirem farmácias, olhavam para uma planta e sabiam o que fazer com ela. Passaram esse conhecimento adiante — de avó para mãe, de mãe para filha — em bilhetes, cadernos manchados de chá e frases ditas em voz baixa: <i>\"toma isso que melhora\"</i>."}, {"t": "p", "x": "Muita coisa se perdeu. Muita coisa sobreviveu."}, {"t": "p", "x": "Este livro é uma tentativa de reunir o que sobreviveu — e o que a ciência moderna, com seus microscópios e seus estudos, acabou confirmando: que o gengibre acalma a náusea, que a aveia ajuda o colesterol, que a camomila afrouxa os nós da noite, que a cúrcuma tem algo de anti-inflamatório, que o alho é amigo do coração."}, {"t": "p", "x": "Não vou lhe prometer milagres. Prometo o contrário: <b>honestidade</b>."}, {"t": "p", "x": "Nenhuma receita deste livro cura doença. Nenhuma substitui o seu médico. O que elas fazem — e não é pouco — é <b>apoiar o corpo</b>. Dar a ele boas condições. Ajudar a digestão a funcionar, o sono a chegar, a imunidade a se sustentar, a inflamação a baixar um pouco, a energia a durar mais. São gestos pequenos. Repetidos todos os dias, viram outra coisa."}, {"t": "p", "x": "Você vai encontrar aqui mais de cem preparos, organizados por <b>aquilo de que o seu corpo precisa</b> — imunidade, peso, açúcar no sangue, coração, digestão, sono, energia, dores, respiração, pele, memória. Todos com ingredientes que você encontra no mercado ou na feira. Todos com o passo a passo, a dose, a frequência e — importante — <b>a cautela</b>."}, {"t": "p", "x": "Use este livro como se usa um caderno de receitas de família: sem pressa, com carinho, tirando o que serve para você."}, {"t": "p", "x": "A saúde não se conquista num gole. Constrói-se numa xícara por dia, durante anos."}, {"t": "p", "x": "<i>Boa leitura — e bom preparo.</i>"}, {"t": "h", "x": "Como usar este livro"}, {"t": "p", "x": "<b>Vá direto ao que você precisa.</b> Não é preciso ler do começo ao fim. Cada seção resolve uma necessidade: se você quer dormir melhor, vá ao capítulo do sono. Se quer apoiar a imunidade no inverno, vá ao da imunidade."}, {"t": "p", "x": "<b>Cada receita segue a mesma estrutura</b>, para você se achar depressa:"}, {"t": "li", "x": "<b>Para que serve</b> — o que ela apoia, sem exagero."}, {"t": "li", "x": "<b>Ingredientes</b> — o que você precisa ter em mãos."}, {"t": "li", "x": "<b>Preparo</b> — o passo a passo, curto e claro."}, {"t": "li", "x": "<b>Como usar</b> — dose e frequência."}, {"t": "li", "x": "<b>Dica do preparo</b> — o detalhe que faz diferença."}, {"t": "li", "x": "<b>Cautela</b> — quem deve evitar, e por quê. <i>Leia sempre esta parte.</i>"}, {"t": "p", "x": "<b>Os quatro princípios que valem para todas as receitas:</b>"}, {"t": "li", "x": "<b>Constância vence intensidade.</b> Uma xícara por dia durante um mês vale mais do que dez xícaras num dia."}, {"t": "li", "x": "<b>Menos é mais.</b> Dobrar a dose não dobra o efeito — só aumenta o risco."}, {"t": "li", "x": "<b>Ingrediente bom, resultado bom.</b> Fresco, limpo, de procedência conhecida."}, {"t": "li", "x": "<b>Escute o corpo.</b> Se algo não lhe cai bem, pare. Simples assim."}, {"t": "p", "x": "<b>Guarde bem:</b> chás e sucos são para consumo no dia. Xaropes, na geladeira, duram o que a receita indicar. Ervas secas, em vidro fechado, longe da luz e do calor."}, {"t": "h", "x": "A despensa da natureza"}, {"t": "p", "x": "Antes de começar, vale conhecer os ingredientes que se repetem ao longo do livro — os \"curingas\" da despensa natural."}, {"t": "p", "x": "<b>Gengibre.</b> Raiz picante e quente. Amiga da digestão, da náusea, da garganta e da circulação. Use fresco sempre que puder."}, {"t": "p", "x": "<b>Cúrcuma (açafrão-da-terra).</b> Pó dourado. Seu composto principal, a curcumina, é estudado por sua ação anti-inflamatória. <b>Sempre com uma pitada de pimenta-do-reino e um fio de gordura boa</b> — é assim que o corpo a aproveita."}, {"t": "p", "x": "<b>Limão.</b> Vitamina C, frescor, alcalinizante depois de metabolizado. Espreme na hora; a vitamina C some com o tempo e o calor."}, {"t": "p", "x": "<b>Alho.</b> O amigo silencioso do coração e da imunidade. Amassado e deixado a descansar 10 minutos antes de usar — é quando forma seus melhores compostos."}, {"t": "p", "x": "<b>Mel.</b> Adoça, acalma a garganta, tem ação antimicrobiana leve. <b>Nunca para bebês menores de 1 ano.</b> Adicione ao chá morno, não fervendo."}, {"t": "p", "x": "<b>Camomila.</b> A erva do fim do dia. Acalma o estômago e a mente."}, {"t": "p", "x": "<b>Hortelã.</b> Alivia o estômago pesado e a cabeça pesada. Refrescante."}, {"t": "p", "x": "<b>Canela.</b> Doce sem açúcar. Estudada no apoio ao controle da glicemia. Prefira a canela do Ceilão se usar todo dia."}, {"t": "p", "x": "<b>Aveia.</b> A fibra que abraça o colesterol e segura a fome."}, {"t": "p", "x": "<b>Vinagre de maçã.</b> Ácido, potente. <b>Sempre diluído</b> — nunca puro, nunca direto no dente."}, {"t": "p", "x": "<b>Semente de linhaça e chia.</b> Fibras, ômega-3 vegetal, saciedade. Linhaça: moa na hora."}, {"t": "p", "x": "<b>Alecrim, salsa, salvia, tomilho.</b> Os temperos que são remédio: antioxidantes, digestivos, aromáticos."}, {"t": "p", "x": "<b>Água.</b> O ingrediente mais esquecido — e o mais importante de todos."}]}, {"id": "x-cautelas", "titulo": "Tabela de cautelas", "sub": "Quem deve ter cuidado com o quê", "capa": "img/rc/r141.webp", "banner": "img/r/r141.webp", "itens": [{"t": "p", "x": "Esta é, talvez, a página mais importante do livro. Leia-a antes de qualquer receita."}, {"t": "h", "x": "Se você toma anticoagulante (varfarina, aspirina, clopidogrel)"}, {"t": "p", "x": "<b>EVITE OU CONSULTE O MÉDICO ANTES DE USAR:</b> ginkgo biloba, alho em quantidade, gengibre em quantidade, cúrcuma em quantidade, castanha-da-índia, garra-do-diabo, cranberry, ginseng, salgueiro. <b>Motivo:</b> todos aumentam o risco de sangramento — e o efeito <b>se soma</b> ao do remédio."}, {"t": "h", "x": "Se você toma remédio para diabetes"}, {"t": "p", "x": "<b>MONITORE A GLICEMIA DE PERTO COM:</b> canela, pata-de-vaca, folha de amora, folha de goiabeira, quiabo, vinagre de maçã, cardo-mariano, ginseng, folha de oliveira. <b>Motivo:</b> podem baixar o açúcar <b>junto</b> com o remédio — risco de hipoglicemia."}, {"t": "h", "x": "Se você toma remédio para pressão"}, {"t": "p", "x": "<b>CUIDADO COM:</b> hibisco, folha de oliveira, alho, urtiga, cavalinha, mulungu, dente-de-leão. <b>Motivo:</b> podem baixar a pressão demais, ou interferir com diuréticos."}, {"t": "h", "x": "Se você está grávida ou amamentando"}, {"t": "p", "x": "<b>EVITE:</b> boldo, espinheira-santa, salgueiro, sálvia (em chá), matricária, quebra-pedra, salsa em quantidade, cavalinha, alecrim (em chá), hibisco, ginseng, valeriana, mulungu, passiflora, tomilho (em chá), goiabeira, cardo-mariano, castanha-da-índia. <b>Regra prática:</b> na gravidez, <b>nada de ervas sem falar com o obstetra.</b> Tempero na comida, sim. Chá medicinal, não por conta própria."}, {"t": "h", "x": "Se é para uma criança"}, {"t": "p", "x": "<b>NUNCA:</b> mel antes de 1 ano · aspirina ou salgueiro (síndrome de Reye) · óleos essenciais (eucalipto, hortelã, cânfora) em bebês · doses de adulto. <b>Regra:</b> pediatra, sempre."}, {"t": "h", "x": "Se você vai passar por cirurgia"}, {"t": "p", "x": "<b>SUSPENDA 1 A 2 SEMANAS ANTES:</b> ginkgo, alho, gengibre, cúrcuma, ginseng, valeriana, matricária. <b>Avise a equipe médica</b> sobre tudo o que você toma — inclusive chás e suplementos \"naturais\"."}, {"t": "h", "x": "Se você tem doença autoimune"}, {"t": "p", "x": "<b>CUIDADO COM:</b> equinácea, ginseng, e outros \"estimulantes da imunidade\" — podem agravar."}, {"t": "h", "x": "Se você tem pedra na vesícula"}, {"t": "p", "x": "<b>EVITE:</b> cúrcuma em quantidade, boldo, alcachofra, dente-de-leão, azeite em jejum, hortelã em excesso. <b>Motivo:</b> estimulam a contração da vesícula — podem provocar uma crise dolorosa."}, {"t": "h", "x": "Se você tem gastrite, refluxo ou úlcera"}, {"t": "p", "x": "<b>EVITE:</b> vinagre puro, hortelã, salgueiro, garra-do-diabo, alho cru em jejum, pimenta, café forte, limão puro em jejum."}, {"t": "h", "x": "Advertência importante"}, {"t": "p", "x": "<b>A REGRA DE OURO DESTE LIVRO:</b> se você toma <b>qualquer</b> medicamento de uso contínuo, mostre este livro ao seu médico ou farmacêutico e pergunte: <i>\"posso usar isto?\"</i>. Leva dois minutos. Pode evitar um problema sério."}]}, {"id": "x-glossario", "titulo": "Glossário das ervas", "sub": "O que é, para que serve e quem não deve usar", "capa": "img/rc/r164.webp", "banner": "img/r/r164.webp", "itens": [{"t": "p", "x": "O quee é, para que serve, e — sobretudo — <b>quem não deve usar</b>. Consulte sempre antes de preparar."}, {"t": "table", "src": "img/livro/livro-tab-p204-205.webp"}, {"t": "table", "src": "img/livro/livro-tab-p205-80.webp"}, {"t": "table", "src": "img/livro/livro-tab-p206-72.webp"}, {"t": "table", "src": "img/livro/livro-tab-p207-72.webp"}]}, {"id": "x-conclusao", "titulo": "Conclusão do livro", "sub": "O que fica", "capa": "img/rc/r166.webp", "banner": "img/r/r166.webp", "itens": [{"t": "h", "x": "O que fica"}, {"t": "p", "x": "Você chegou ao fim de mais de cem receitas. Antes de fechar o livro, permita-me três verdades. <b>A PRIMEIRA: NADA AQUI É MILAGRE.</b> Se você leu esperando encontrar a fórmula secreta que cura tudo, sinto muito — ela não existe, nem neste livro, nem em nenhum outro. O que existe é isto: um copo de água com limão pela manhã, uma xícara de camomila à noite, um punhado de nozes à tarde, o azeite cru sobre a salada, a aveia no café da manhã. Gestos pequenos. Quase invisíveis. E é exatamente por isso que funcionam. Porque são pequenos o bastante para caberem na sua vida real — e repetíveis o bastante para, ao longo dos anos, mudarem alguma coisa. <b>A SEGUNDA: A NATUREZA É POTENTE, E POTÊNCIA EXIGE RESPEITO.</b> Uma planta que age no corpo é, por definição, capaz de causar efeitos. O salgueiro que alivia a dor é o mesmo que fere um estômago frágil. O ginkgo que ajuda a memória é o mesmo que faz sangrar quem toma anticoagulante. \"Natural\" nunca quis dizer \"inofensivo\" — quer dizer apenas \"não fabricado\". Por isso cada receita deste livro veio com a sua cautela. Elas não são texto miúdo. São parte da receita. <b>A TERCEIRA: NADA DISTO SUBSTITUI O SEU MÉDICO.</b> Se algo dói, persiste, piora ou assusta — vá. Faça o exame. Ouça o diagnóstico. Tome o remédio, se ele for necessário. A medicina moderna salva vidas todos os dias, e nenhuma xícara de chá vai fazer o que um antibiótico faz numa pneumonia. O que este livro oferece é o <b>OUTRO LADO</b> desse mesmo cuidado: o dia comum. Aquele em que você não está doente, mas também não está tão bem quanto poderia. É aí que a natureza tem mais a dar. É aí que a prevenção mora. Feche o livro. Vá até a cozinha. Ferva água. Escolha <b>UMA</b> receita — só uma — e faça hoje. Amanhã, faça de novo. É assim que a saúde se constrói: não num gole, mas numa xícara por dia, durante anos. <i>Cuide-se. Todos os dias.</i>"}, {"t": "box", "tipo": "nota", "titulo": "Nota final e advertência", "itens": [{"t": "p", "x": "<b>AS INFORMAÇÕES CONTIDAS NESTE LIVRO TÊM FINALIDADE EXCLUSIVAMENTE EDUCATIVA E INFORMATIVA. NÃO CONSTITUEM ACONSELHAMENTO MÉDICO, DIAGNÓSTICO OU TRATAMENTO, E NÃO SUBSTITUEM, EM NENHUMA HIPÓTESE, A CONSULTA COM UM PROFISSIONAL DE SAÚDE QUALIFICADO.</b>"}]}, {"t": "p", "x": "As receitas reunidas aqui pertencem à tradição popular e ao uso alimentar comum de plantas, frutas e temperos. Apoiam o bem-estar; não curam doenças. <b>CONSULTE SEMPRE O SEU MÉDICO</b> antes de iniciar qualquer preparo, especialmente se você: tem alguma condição de saúde; faz uso de medicamentos (as plantas interagem com remédios); está grávida ou amamentando; vai oferecer algo a uma criança ou a um idoso; tem alergias; ou vai passar por cirurgia. <b>NUNCA INTERROMPA NEM SUBSTITUA UM TRATAMENTO MÉDICO</b> por conta própria com base neste livro. Em caso de sintomas fortes, persistentes ou que piorem, <b>PROCURE ATENDIMENTO MÉDICO IMEDIATAMENTE</b>. O autor e o editor não se responsabilizam por qualquer consequência decorrente do uso indevido das informações aqui apresentadas."}]}];
